  const int grid = p.B * 49 / T;
  void* args[] = {(void*)&p};
  e = cudaLaunchCooperativeKernel(T == 1 ? (const void*)m_kernel<1> : (const void*)m_kernel<2>, dim3(grid), dim3(NTH), args,
                                  (size_t)SMEM_TOTAL, (cudaStream_t)stream);
