files.content:
// 045_fused_linear_gelu_grn_linear, lineage B (r1 E2): hidden-slice fan-out for N <= 3136 tokens.
//   e2: grid = token tiles x 4 hidden slices of 128 (one wave, 1 CTA/SM, cooperative). Each CTA LDGs its fp32 slices
//       W1[slice,:], W2[:,slice] and its x tile, splits them into fp16 hi/lo SW128 smem images, runs GEMM1 swap-AB
//       (D1[hid][tok], FP16x3) into TMEM, + b1, A&S GELU, per-channel sumsq red.add into gsum[b][512] (zeroed by CTA 0
//       behind a flag), one grid counter (departure reset), GRN scale, x2 = gw*(h*nf) + gb + h split hi/lo, GEMM2
//       swap-AB (D2[out][tok], main + cross accumulators) and red.add into out (prefilled with b2 by the slice-0 CTA).
//   other shapes: r0 fp32 SIMT, three launches.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct E2Params {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; float* gsum; int B; int HW; float eps;
};

// [0] gsum-zeroed flag, [1] arrivals, [2] departures; the last departer resets all three for the next call
__device__ unsigned int g_e2ctr[4];

namespace {
// ------------------------------------------------------------------ r0 fallback (fp32 SIMT, 3 launches)
constexpr int D = 128, HID = 512, TM = 64, NC = 64, NT = 256;
constexpr int NCHUNK = HID / NC;
constexpr int LDK = D + 4;
constexpr int LDH = NC + 4;

__device__ __forceinline__ float gelu_erf(float v) {
  return v * 0.5f * (1.0f + erff(v * 0.7071067811865476f));
}

__device__ __forceinline__ void load_rows128(float* dst, const float* src, int nrows, int nvalid, int tid) {
  for (int i = tid; i < nrows * (D / 4); i += NT) {
    int r = i >> 5, k4 = (i & 31) << 2;
    float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
    if (r < nvalid) v = __ldg(reinterpret_cast<const float4*>(src + (size_t)r * D + k4));
    *reinterpret_cast<float4*>(dst + r * LDK + k4) = v;
  }
}

__device__ __forceinline__ void gemm1(float (&acc)[4][4], const float* As, const float* Ws, int tm, int tn) {
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;
#pragma unroll 4
  for (int k = 0; k < D; k += 4) {
    float4 a[4], w[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(As + (tm * 4 + i) * LDK + k);
#pragma unroll
    for (int j = 0; j < 4; ++j) w[j] = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDK + k);
#pragma unroll
    for (int i = 0; i < 4; ++i)
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        acc[i][j] = fmaf(a[i].x, w[j].x, acc[i][j]);
        acc[i][j] = fmaf(a[i].y, w[j].y, acc[i][j]);
        acc[i][j] = fmaf(a[i].z, w[j].z, acc[i][j]);
        acc[i][j] = fmaf(a[i].w, w[j].w, acc[i][j]);
      }
  }
}

__global__ void __launch_bounds__(NT) k_stats(const float* __restrict__ x, const float* __restrict__ w1,
                                              const float* __restrict__ b1, float* __restrict__ part,
                                              int HW, int tiles) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Red = Ws + NC * LDK;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  float* pout = part + ((size_t)b * tiles + tile) * HID;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
    float sq[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      float bias = __ldg(b1 + c * NC + tn + 16 * j);
      float s = 0.f;
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        if (tm * 4 + i < rows) s = fmaf(h, h, s);
      }
      s += __shfl_xor_sync(0xffffffffu, s, 16);
      sq[j] = s;
    }
    if (lane < 16) {
#pragma unroll
      for (int j = 0; j < 4; ++j) Red[warp * NC + tn + 16 * j] = sq[j];
    }
    __syncthreads();
    if (tid < NC) {
      float s = 0.f;
#pragma unroll
      for (int w = 0; w < NT / 32; ++w) s += Red[w * NC + tid];
      pout[c * NC + tid] = s;
    }
  }
}

__global__ void __launch_bounds__(HID) k_grn(const float* __restrict__ part, float* __restrict__ nf, int tiles,
                                             float eps) {
  __shared__ float red[HID / 32];
  const int b = blockIdx.x, c = threadIdx.x;
  const float* p = part + (size_t)b * tiles * HID + c;
  float s = 0.f;
  for (int t = 0; t < tiles; ++t) s += p[(size_t)t * HID];
  float g = __fsqrt_rn(s);
  float r = g;
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) r += __shfl_xor_sync(0xffffffffu, r, o);
  if ((c & 31) == 0) red[c >> 5] = r;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int w = 0; w < HID / 32; ++w) tot += red[w];
  float mean = __fdiv_rn(tot, (float)HID);
  nf[(size_t)b * HID + c] = __fdiv_rn(g, mean + eps);
}

__global__ void __launch_bounds__(NT) k_main(const float* __restrict__ x, const float* __restrict__ w1,
                                             const float* __restrict__ b1, const float* __restrict__ gw,
                                             const float* __restrict__ gb, const float* __restrict__ w2,
                                             const float* __restrict__ b2, const float* __restrict__ nf,
                                             float* __restrict__ out, int HW) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Hs = Ws + D * LDH;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  const float* nfb = nf + (size_t)b * HID;
  float acc2[4][8];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 8; ++j) acc2[i][j] = 0.f;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int n = c * NC + tn + 16 * j;
      const float bias = __ldg(b1 + n), g = __ldg(gw + n), be = __ldg(gb + n), f = __ldg(nfb + n);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        Hs[(tm * 4 + i) * LDH + tn + 16 * j] = g * (h * f) + be + h;
      }
    }
    __syncthreads();
    for (int i = tid; i < D * (NC / 4); i += NT) {
      int o = i >> 4, k4 = (i & 15) << 2;
      *reinterpret_cast<float4*>(Ws + o * LDH + k4) =
          __ldg(reinterpret_cast<const float4*>(w2 + (size_t)o * HID + c * NC + k4));
    }
    __syncthreads();
#pragma unroll 2
    for (int k = 0; k < NC; k += 4) {
      float4 a[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(Hs + (tm * 4 + i) * LDH + k);
#pragma unroll
      for (int j = 0; j < 8; ++j) {
        float4 w = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDH + k);
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          acc2[i][j] = fmaf(a[i].x, w.x, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].y, w.y, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].z, w.z, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].w, w.w, acc2[i][j]);
        }
      }
    }
  }
  float* ob = out + ((size_t)b * HW + m0) * D;
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int o = tn + 16 * j;
    const float bias = __ldg(b2 + o);
#pragma unroll
    for (int i = 0; i < 4; ++i)
      if (tm * 4 + i < rows) ob[(size_t)(tm * 4 + i) * D + o] = acc2[i][j] + bias;
  }
}

constexpr int SMEM_STATS = (TM * LDK + NC * LDK + (NT / 32) * NC) * 4;
constexpr int SMEM_MAIN = (TM * LDK + D * LDH + TM * LDH) * 4;
static_assert(D * LDH >= NC * LDK, "Ws must hold either chunk");

// ------------------------------------------------------------------ e2: hidden-slice fan-out (tcgen05 FP16x3)
constexpr int E2_NTH = 512;
constexpr int OFF_W1H = 0, OFF_W1L = 32768;      // W1 slice [128 hid][128 k] K-major SW128, hi / lo
constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
constexpr int OFF_VEC = 196608;                  // b1, gw, gb, nf slices [128] each
constexpr int OFF_SSP = 198656;                  // sumsq partials [4 column quarters][128]
constexpr int OFF_RED = 200704;                  // [16]
constexpr int OFF_BAR = 200960;                  // 2 mbarriers + TMEM slot
constexpr int E2_SMEM = 201024 + 1024;

__device__ __forceinline__ uint32_t s_addr(const void* q) { return (uint32_t)__cvta_generic_to_shared(q); }
__device__ __forceinline__ void mbar_init(uint32_t b, uint32_t n) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(b), "r"(n)); }
__device__ __forceinline__ void mbar_wait(uint32_t b, uint32_t par) {
  asm volatile("{\n.reg .pred P;\nWAIT_%=:\nmbarrier.try_wait.parity.shared::cta.b64 P, [%0], %1;\n@!P bra WAIT_%=;\n}\n" ::"r"(b), "r"(par) : "memory");
}
__device__ __forceinline__ void fence_proxy_async() { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); }
__device__ __forceinline__ void tc_before() { asm volatile("tcgen05.fence::before_thread_sync;" ::: "memory"); }
__device__ __forceinline__ void tc_after() { asm volatile("tcgen05.fence::after_thread_sync;" ::: "memory"); }
__device__ __forceinline__ uint64_t sdesc(uint32_t addr) {  // K-major SWIZZLE_128B, SBO 1024, sm100 descriptor version 1
  return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | (1ull << 46) | (2ull << 61);
}
// kind::f16: fp32 D, fp16 A/B, both K-major, M = 128
__device__ __forceinline__ uint32_t idesc_kk(int n) { return (1u << 4) | ((uint32_t)(n >> 3) << 17) | ((128u >> 4) << 24); }
__device__ __forceinline__ void mma_issue(uint32_t d, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  asm volatile("{\n.reg .pred E, A;\nelect.sync _|E, 0xffffffff;\nsetp.ne.u32 A, %4, 0;\n"
               "@E tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, A;\n}\n" ::"r"(d), "l"(a), "l"(b), "r"(id), "r"(acc) : "memory");
}
__device__ __forceinline__ void mma_commit(uint32_t bar) {
  asm volatile("{\n.reg .pred E;\nelect.sync _|E, 0xffffffff;\n"
               "@E tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}\n" ::"r"(bar) : "memory");
}
template <int N>
__device__ __forceinline__ void tmem_ld(uint32_t ta, float (&v)[N]) {
  uint32_t r[N];
#pragma unroll
  for (int i = 0; i < N / 4; i++)
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r[4 * i]), "=r"(r[4 * i + 1]), "=r"(r[4 * i + 2]), "=r"(r[4 * i + 3]) : "r"(ta + 4 * i) : "memory");
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
  for (int i = 0; i < N; i++) {
    asm volatile("" : "+r"(r[i]));  // uses stay behind the wait
    v[i] = __uint_as_float(r[i]);
  }
}
__device__ __forceinline__ uint32_t ld_acquire(const unsigned int* q) {
  uint32_t v;
  asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(v) : "l"(q) : "memory");
  return v;
}
__device__ __forceinline__ void red_release(unsigned int* q, uint32_t v) {
  asm volatile("red.release.gpu.global.add.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ void st_release(unsigned int* q, uint32_t v) {
  asm volatile("st.release.gpu.global.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// GELU (erf form) on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0)   (#129 gelu2 without the sumsq)
__device__ __forceinline__ void gelu2(float& x0, float& x1) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  f2unpack(add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f))), x0, x1);
}
// 4 consecutive k of row r into the hi and lo K-major SW128 images (atom = 64 k = 128 B per row)
__device__ __forceinline__ void put_hilo(unsigned char* sm, int offh, int offl, int atom_bytes, int r, int c4, float4 v) {
  const int off = (c4 >> 4) * atom_bytes + r * 128 + ((((c4 >> 1) & 7) ^ (r & 7)) << 4) + (c4 & 1) * 8;
  const __half2 h01 = __floats2half2_rn(v.x, v.y), h23 = __floats2half2_rn(v.z, v.w);
  const float2 f01 = __half22float2(h01), f23 = __half22float2(h23);
  const __half2 l01 = __floats2half2_rn(v.x - f01.x, v.y - f01.y), l23 = __floats2half2_rn(v.z - f23.x, v.w - f23.y);
  *reinterpret_cast<uint2*>(sm + offh + off) = make_uint2(h2u(h01), h2u(h23));
  *reinterpret_cast<uint2*>(sm + offl + off) = make_uint2(h2u(l01), h2u(l23));
}

template <int TT>
__global__ void __launch_bounds__(E2_NTH, 1) e2_kernel(const E2Params p) {
  constexpr int NP = (TT + 15) / 16 * 16;  // MMA N (tokens, padded)
  constexpr int CW = NP / 4;               // columns per thread in the epilogues
  constexpr int XATOM = NP * 128;          // bytes per 64-k atom of a token-row image
  constexpr int NXL = NP / 16;             // x float4 per thread
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int slice = blockIdx.x & 3, tile = blockIdx.x >> 2, tok0 = tile * TT, b = tok0 / p.HW;
  float* s_b1 = (float*)(sm + OFF_VEC);
  float* s_gw = s_b1 + 128;
  float* s_gb = s_b1 + 256;
  float* s_nf = s_b1 + 384;
  float* s_ssp = (float*)(sm + OFF_SSP);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar1 = sb + OFF_BAR, bar2 = bar1 + 8;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 16);
  unsigned int* ctr = g_e2ctr;

  // ---- every global load up front: W1 slice (contiguous 64 KB), x tile, W2 slice (128 rows x 512 B), b1/gw/gb slices
  float4 vw1[8], vx[NXL], vw2[8], vv = make_float4(0.f, 0.f, 0.f, 0.f);
  const float4* w1s = reinterpret_cast<const float4*>(p.w1 + (size_t)slice * 128 * 128);
#pragma unroll
  for (int i = 0; i < 8; i++) vw1[i] = __ldg(w1s + tid + E2_NTH * i);
  const float4* xs = reinterpret_cast<const float4*>(p.x + (size_t)tok0 * 128);
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    vx[i] = ((f >> 5) < TT) ? __ldg(xs + f) : make_float4(0.f, 0.f, 0.f, 0.f);
  }
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    vw2[i] = __ldg(reinterpret_cast<const float4*>(p.w2 + (size_t)(f >> 5) * 512 + slice * 128) + (f & 31));
  }
  if (tid < 96) {
    const float* src = tid < 32 ? p.b1 : (tid < 64 ? p.gw : p.gb);
    vv = __ldg(reinterpret_cast<const float4*>(src + slice * 128) + (tid & 31));
  }
  if (tid == 0) {
    mbar_init(bar1, 1);
    mbar_init(bar2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  if (blockIdx.x == 0)
    for (int i = tid; i < p.B * 512; i += E2_NTH) p.gsum[i] = 0.f;
  if (tid < 96) reinterpret_cast<float4*>(s_b1)[tid] = vv;
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W1H, OFF_W1L, 16384, f >> 5, f & 31, vw1[i]);
  }
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_XH, OFF_XL, XATOM, f >> 5, f & 31, vx[i]);
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  if (blockIdx.x == 0 && tid == 0) { __threadfence(); st_release(ctr, 1u); }
  const uint32_t tmem = *s_tmem;
  // ---- GEMM1 swap-AB: D1[hid][tok] = W1h.Xh + W1h.Xl + W1l.Xh, K = 128 (cross terms first)
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int pr = 0; pr < 3; pr++) {
      const uint32_t A = (pr == 1) ? OFF_W1L : OFF_W1H;
      const uint32_t Bo = (pr == 0) ? OFF_XL : OFF_XH;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar1);
  }
  // ---- behind GEMM1: W2 slice image; the slice-0 CTA prefills its out rows with b2
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W2H, OFF_W2L, 16384, f >> 5, f & 31, vw2[i]);
  }
  fence_proxy_async();
  if (slice == 0) {
    const float4* b24 = reinterpret_cast<const float4*>(p.b2);
    float4* o4 = reinterpret_cast<float4*>(p.out + (size_t)tok0 * 128);
    for (int i = tid; i < TT * 32; i += E2_NTH) o4[i] = __ldg(b24 + (i & 31));
  }
  // ---- GEMM1 epilogue: + b1, GELU, masked per-channel sumsq; h stays in registers across the barrier
  mbar_wait(bar1, 0);
  tc_after();
  const int q = warp & 3, cq = warp >> 2, hid = 32 * q + lane;
  const uint32_t tq = tmem + ((uint32_t)(32 * q) << 16) + cq * CW;
  float h[CW];
  tmem_ld<CW>(tq, h);
  {
    const float bk = s_b1[hid];
    float ss = 0.f;
#pragma unroll
    for (int e = 0; e < CW; e += 2) {
      float x0 = h[e] + bk, x1 = h[e + 1] + bk;
      gelu2(x0, x1);
      const int t = cq * CW + e;
      if (t >= TT) x0 = 0.f;
      if (t + 1 >= TT) x1 = 0.f;
      h[e] = x0;
      h[e + 1] = x1;
      ss = fmaf(x0, x0, ss);
      ss = fmaf(x1, x1, ss);
    }
    s_ssp[cq * 128 + hid] = ss;
  }
  if (tid == 0) { while (ld_acquire(ctr) == 0u) { } }
  __syncthreads();
  if (tid < 128) atomicAdd(p.gsum + b * 512 + slice * 128 + tid, s_ssp[tid] + s_ssp[128 + tid] + s_ssp[256 + tid] + s_ssp[384 + tid]);
  __syncthreads();
  // ---- grid barrier: one arrival counter; the last departer resets the counters
  if (tid == 0) {
    __threadfence();
    red_release(ctr + 1, 1u);
    while (ld_acquire(ctr + 1) < gridDim.x) { }
    const unsigned old = atomicAdd(ctr + 2, 1u);
    if (old == gridDim.x - 1) {
      atomicExch(ctr, 0u);
      atomicExch(ctr + 1, 0u);
      atomicExch(ctr + 2, 0u);
    }
  }
  __syncthreads();
  // ---- GRN: G = sqrt(gsum), nf = G / (mean G + eps) for this slice
  {
    const float g = __fsqrt_rn(__ldcg(p.gsum + b * 512 + tid));
    const float ws = warp_sum(g);
    if (lane == 0) s_red[warp] = ws;
    __syncthreads();
    float tot = 0.f;
#pragma unroll
    for (int i = 0; i < 16; i++) tot += s_red[i];
    const float mean = __fdiv_rn(tot, 512.f);
    if ((tid >> 7) == slice) s_nf[tid & 127] = __fdiv_rn(g, mean + p.eps);
    __syncthreads();
  }
  // ---- x2 = gw*(h*nf) + gb + h, split hi/lo into the K-major token-row images (x space)
  {
    const float nfk = s_nf[hid], gwk = s_gw[hid], gbk = s_gb[hid];
    const int at = (hid >> 6) * XATOM, ch = (hid >> 3) & 7, sub = (hid & 7) * 2;
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      const float v = h[e];
      const float x2 = gwk * (v * nfk) + gbk + v;
      const __half hi = __float2half_rn(x2);
      const __half lo = __float2half_rn(x2 - __half2float(hi));
      const int off = at + t * 128 + ((ch ^ (t & 7)) << 4) + sub;
      *reinterpret_cast<__half*>(sm + OFF_XH + off) = hi;
      *reinterpret_cast<__half*>(sm + OFF_XL + off) = lo;
    }
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  // ---- GEMM2 swap-AB: D2[out][tok] = W2h.X2h (cols 128..) and W2h.X2l + W2l.X2h (cols 256..), K = 128
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int kk = 0; kk < 8; kk++) {
      const uint32_t w = (kk & 3) * 32;
      mma_issue(tmem + 128, sdesc(sb + OFF_W2H + (kk >> 2) * 16384 + w), sdesc(sb + OFF_XH + (kk >> 2) * XATOM + w), id,
                kk ? 1u : 0u);
    }
#pragma unroll
    for (int pr = 0; pr < 2; pr++) {
      const uint32_t A = pr ? OFF_W2L : OFF_W2H;
      const uint32_t Bo = pr ? OFF_XH : OFF_XL;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem + 256, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar2);
  }
  mbar_wait(bar2, 0);
  tc_after();
  {
    float m[CW], c[CW];
    tmem_ld<CW>(tq + 128, m);
    tmem_ld<CW>(tq + 256, c);
    float* ob = p.out + (size_t)tok0 * 128 + hid;  // hid = output channel here
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      if (t < TT) atomicAdd(ob + (size_t)t * 128, m[e] + c[e]);
    }
  }
  tc_before();
  __syncthreads();
  if (warp == 0) {
    tc_after();
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory");
  }
}

template <int TT>
const char* e2_launch(const E2Params& p, int N, cudaStream_t stream) {
  static bool attr_set = false;
  cudaError_t e;
  if (!attr_set) {
    e = cudaFuncSetAttribute(e2_kernel<TT>, cudaFuncAttributeMaxDynamicSharedMemorySize, E2_SMEM);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    attr_set = true;
  }
  E2Params q = p;
  void* args[] = {(void*)&q};
  e = cudaLaunchCooperativeKernel((const void*)e2_kernel<TT>, dim3(4 * (N / TT)), dim3(E2_NTH), args, (size_t)E2_SMEM, stream);
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
}  // namespace

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream) {
  const int N = B * HW;
  // e2 path: smallest token tile that divides HW and keeps 4 slices x tiles within one wave of 148 CTAs
  int tt = 0;
  const int cands[3] = {28, 49, 98};
  for (int i = 0; i < 3 && !tt; i++)
    if (HW % cands[i] == 0 && 4 * (N / cands[i]) <= 148) tt = cands[i];
  if (tt) {
    E2Params p{x, w1, b1, gw, gb, w2, b2, out, nf, B, HW, eps};
    if (tt == 28) return e2_launch<28>(p, N, stream);
    if (tt == 49) return e2_launch<49>(p, N, stream);
    return e2_launch<98>(p, N, stream);
  }
  static bool attrs_set = false;
  if (!attrs_set) {
    cudaFuncSetAttribute(k_stats, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_STATS);
    cudaFuncSetAttribute(k_main, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_MAIN);
    attrs_set = true;
  }
  const int tiles = (HW + TM - 1) / TM;
  dim3 grid(tiles, B);
  k_stats<<<grid, NT, SMEM_STATS, stream>>>(x, w1, b1, part, HW, tiles);
  k_grn<<<B, HID, 0, stream>>>(part, nf, tiles, eps);
  k_main<<<grid, NT, SMEM_MAIN, stream>>>(x, w1, b1, gw, gb, w2, b2, nf, out, HW);
  return nullptr;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream);

void run(torch::Tensor hidden_states, torch::Tensor pwconv1_weight, torch::Tensor pwconv1_bias,
         torch::Tensor grn_weight, torch::Tensor grn_bias, torch::Tensor pwconv2_weight, torch::Tensor pwconv2_bias,
         double eps, torch::Tensor output) {
  TORCH_CHECK(hidden_states.is_cuda() && hidden_states.scalar_type() == torch::kFloat32, "fp32 CUDA input");
  TORCH_CHECK(hidden_states.dim() == 4 && hidden_states.size(3) == 128, "[B,H,W,128]");
  TORCH_CHECK(pwconv1_weight.size(0) == 512 && pwconv1_weight.size(1) == 128, "W1 [512,128]");
  TORCH_CHECK(pwconv2_weight.size(0) == 128 && pwconv2_weight.size(1) == 512, "W2 [128,512]");
  for (auto* t : {&hidden_states, &pwconv1_weight, &pwconv1_bias, &grn_weight, &grn_bias, &pwconv2_weight,
                  &pwconv2_bias, &output})
    TORCH_CHECK(t->is_contiguous(), "contiguous tensors required");
  const c10::cuda::CUDAGuard guard(hidden_states.device());
  const int B = (int)hidden_states.size(0);
  const int HW = (int)(hidden_states.size(1) * hidden_states.size(2));
  const int tiles = (HW + 63) / 64;
  auto part = torch::empty({(int64_t)B * tiles * 512}, hidden_states.options());
  auto nf = torch::empty({(int64_t)B * 512}, hidden_states.options());
  const char* err = launch_grn_mlp(hidden_states.data_ptr<float>(), pwconv1_weight.data_ptr<float>(),
                                   pwconv1_bias.data_ptr<float>(), grn_weight.data_ptr<float>(), grn_bias.data_ptr<float>(),
                                   pwconv2_weight.data_ptr<float>(), pwconv2_bias.data_ptr<float>(), (float)eps,
                                   output.data_ptr<float>(), part.data_ptr<float>(), nf.data_ptr<float>(), B, HW,
                                   at::cuda::getCurrentCUDAStream());
  TORCH_CHECK(err == nullptr, err ? err : "");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "fused linear-gelu-grn-linear"); }

// 045_fused_linear_gelu_grn_linear, lineage B (r1 E2): hidden-slice fan-out for N <= 3136 tokens.
//   e2: grid = token tiles x 4 hidden slices of 128 (one wave, 1 CTA/SM, cooperative). Each CTA LDGs its fp32 slices
//       W1[slice,:], W2[:,slice] and its x tile, splits them into fp16 hi/lo SW128 smem images, runs GEMM1 swap-AB
//       (D1[hid][tok], FP16x3) into TMEM, + b1, A&S GELU, per-channel sumsq red.add into gsum[b][512] (zeroed by CTA 0
//       behind a flag), one grid counter (departure reset), GRN scale, x2 = gw*(h*nf) + gb + h split hi/lo, GEMM2
//       swap-AB (D2[out][tok], main + cross accumulators) and red.add into out (prefilled with b2 by the slice-0 CTA).
//   other shapes: r0 fp32 SIMT, three launches.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct E2Params {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; float* gsum; int B; int HW; float eps;
};

// [0] gsum-zeroed flag, [1] arrivals, [2] departures; the last departer resets all three for the next call
__device__ unsigned int g_e2ctr[4];

namespace {
// ------------------------------------------------------------------ r0 fallback (fp32 SIMT, 3 launches)
constexpr int D = 128, HID = 512, TM = 64, NC = 64, NT = 256;
constexpr int NCHUNK = HID / NC;
constexpr int LDK = D + 4;
constexpr int LDH = NC + 4;

__device__ __forceinline__ float gelu_erf(float v) {
  return v * 0.5f * (1.0f + erff(v * 0.7071067811865476f));
}

__device__ __forceinline__ void load_rows128(float* dst, const float* src, int nrows, int nvalid, int tid) {
  for (int i = tid; i < nrows * (D / 4); i += NT) {
    int r = i >> 5, k4 = (i & 31) << 2;
    float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
    if (r < nvalid) v = __ldg(reinterpret_cast<const float4*>(src + (size_t)r * D + k4));
    *reinterpret_cast<float4*>(dst + r * LDK + k4) = v;
  }
}

__device__ __forceinline__ void gemm1(float (&acc)[4][4], const float* As, const float* Ws, int tm, int tn) {
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;
#pragma unroll 4
  for (int k = 0; k < D; k += 4) {
    float4 a[4], w[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(As + (tm * 4 + i) * LDK + k);
#pragma unroll
    for (int j = 0; j < 4; ++j) w[j] = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDK + k);
#pragma unroll
    for (int i = 0; i < 4; ++i)
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        acc[i][j] = fmaf(a[i].x, w[j].x, acc[i][j]);
        acc[i][j] = fmaf(a[i].y, w[j].y, acc[i][j]);
        acc[i][j] = fmaf(a[i].z, w[j].z, acc[i][j]);
        acc[i][j] = fmaf(a[i].w, w[j].w, acc[i][j]);
      }
  }
}

__global__ void __launch_bounds__(NT) k_stats(const float* __restrict__ x, const float* __restrict__ w1,
                                              const float* __restrict__ b1, float* __restrict__ part,
                                              int HW, int tiles) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Red = Ws + NC * LDK;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  float* pout = part + ((size_t)b * tiles + tile) * HID;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
    float sq[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      float bias = __ldg(b1 + c * NC + tn + 16 * j);
      float s = 0.f;
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        if (tm * 4 + i < rows) s = fmaf(h, h, s);
      }
      s += __shfl_xor_sync(0xffffffffu, s, 16);
      sq[j] = s;
    }
    if (lane < 16) {
#pragma unroll
      for (int j = 0; j < 4; ++j) Red[warp * NC + tn + 16 * j] = sq[j];
    }
    __syncthreads();
    if (tid < NC) {
      float s = 0.f;
#pragma unroll
      for (int w = 0; w < NT / 32; ++w) s += Red[w * NC + tid];
      pout[c * NC + tid] = s;
    }
  }
}

__global__ void __launch_bounds__(HID) k_grn(const float* __restrict__ part, float* __restrict__ nf, int tiles,
                                             float eps) {
  __shared__ float red[HID / 32];
  const int b = blockIdx.x, c = threadIdx.x;
  const float* p = part + (size_t)b * tiles * HID + c;
  float s = 0.f;
  for (int t = 0; t < tiles; ++t) s += p[(size_t)t * HID];
  float g = __fsqrt_rn(s);
  float r = g;
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) r += __shfl_xor_sync(0xffffffffu, r, o);
  if ((c & 31) == 0) red[c >> 5] = r;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int w = 0; w < HID / 32; ++w) tot += red[w];
  float mean = __fdiv_rn(tot, (float)HID);
  nf[(size_t)b * HID + c] = __fdiv_rn(g, mean + eps);
}

__global__ void __launch_bounds__(NT) k_main(const float* __restrict__ x, const float* __restrict__ w1,
                                             const float* __restrict__ b1, const float* __restrict__ gw,
                                             const float* __restrict__ gb, const float* __restrict__ w2,
                                             const float* __restrict__ b2, const float* __restrict__ nf,
                                             float* __restrict__ out, int HW) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Hs = Ws + D * LDH;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  const float* nfb = nf + (size_t)b * HID;
  float acc2[4][8];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 8; ++j) acc2[i][j] = 0.f;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int n = c * NC + tn + 16 * j;
      const float bias = __ldg(b1 + n), g = __ldg(gw + n), be = __ldg(gb + n), f = __ldg(nfb + n);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        Hs[(tm * 4 + i) * LDH + tn + 16 * j] = g * (h * f) + be + h;
      }
    }
    __syncthreads();
    for (int i = tid; i < D * (NC / 4); i += NT) {
      int o = i >> 4, k4 = (i & 15) << 2;
      *reinterpret_cast<float4*>(Ws + o * LDH + k4) =
          __ldg(reinterpret_cast<const float4*>(w2 + (size_t)o * HID + c * NC + k4));
    }
    __syncthreads();
#pragma unroll 2
    for (int k = 0; k < NC; k += 4) {
      float4 a[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(Hs + (tm * 4 + i) * LDH + k);
#pragma unroll
      for (int j = 0; j < 8; ++j) {
        float4 w = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDH + k);
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          acc2[i][j] = fmaf(a[i].x, w.x, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].y, w.y, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].z, w.z, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].w, w.w, acc2[i][j]);
        }
      }
    }
  }
  float* ob = out + ((size_t)b * HW + m0) * D;
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int o = tn + 16 * j;
    const float bias = __ldg(b2 + o);
#pragma unroll
    for (int i = 0; i < 4; ++i)
      if (tm * 4 + i < rows) ob[(size_t)(tm * 4 + i) * D + o] = acc2[i][j] + bias;
  }
}

constexpr int SMEM_STATS = (TM * LDK + NC * LDK + (NT / 32) * NC) * 4;
constexpr int SMEM_MAIN = (TM * LDK + D * LDH + TM * LDH) * 4;
static_assert(D * LDH >= NC * LDK, "Ws must hold either chunk");

// ------------------------------------------------------------------ e2: hidden-slice fan-out (tcgen05 FP16x3)
constexpr int E2_NTH = 512;
constexpr int OFF_W1H = 0, OFF_W1L = 32768;      // W1 slice [128 hid][128 k] K-major SW128, hi / lo
constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
constexpr int OFF_VEC = 196608;                  // b1, gw, gb, nf slices [128] each
constexpr int OFF_SSP = 198656;                  // sumsq partials [4 column quarters][128]
constexpr int OFF_RED = 200704;                  // [16]
constexpr int OFF_BAR = 200960;                  // 2 mbarriers + TMEM slot
constexpr int E2_SMEM = 201024 + 1024;

__device__ __forceinline__ uint32_t s_addr(const void* q) { return (uint32_t)__cvta_generic_to_shared(q); }
__device__ __forceinline__ void mbar_init(uint32_t b, uint32_t n) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(b), "r"(n)); }
__device__ __forceinline__ void mbar_wait(uint32_t b, uint32_t par) {
  asm volatile("{\n.reg .pred P;\nWAIT_%=:\nmbarrier.try_wait.parity.shared::cta.b64 P, [%0], %1;\n@!P bra WAIT_%=;\n}\n" ::"r"(b), "r"(par) : "memory");
}
__device__ __forceinline__ void fence_proxy_async() { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); }
__device__ __forceinline__ void tc_before() { asm volatile("tcgen05.fence::before_thread_sync;" ::: "memory"); }
__device__ __forceinline__ void tc_after() { asm volatile("tcgen05.fence::after_thread_sync;" ::: "memory"); }
__device__ __forceinline__ uint64_t sdesc(uint32_t addr) {  // K-major SWIZZLE_128B, SBO 1024, sm100 descriptor version 1
  return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | (1ull << 46) | (2ull << 61);
}
// kind::f16: fp32 D, fp16 A/B, both K-major, M = 128
__device__ __forceinline__ uint32_t idesc_kk(int n) { return (1u << 4) | ((uint32_t)(n >> 3) << 17) | ((128u >> 4) << 24); }
__device__ __forceinline__ void mma_issue(uint32_t d, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  asm volatile("{\n.reg .pred E, A;\nelect.sync _|E, 0xffffffff;\nsetp.ne.u32 A, %4, 0;\n"
               "@E tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, A;\n}\n" ::"r"(d), "l"(a), "l"(b), "r"(id), "r"(acc) : "memory");
}
__device__ __forceinline__ void mma_commit(uint32_t bar) {
  asm volatile("{\n.reg .pred E;\nelect.sync _|E, 0xffffffff;\n"
               "@E tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}\n" ::"r"(bar) : "memory");
}
template <int N>
__device__ __forceinline__ void tmem_ld(uint32_t ta, float (&v)[N]) {
  uint32_t r[N];
#pragma unroll
  for (int i = 0; i < N / 4; i++)
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r[4 * i]), "=r"(r[4 * i + 1]), "=r"(r[4 * i + 2]), "=r"(r[4 * i + 3]) : "r"(ta + 4 * i) : "memory");
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
  for (int i = 0; i < N; i++) {
    asm volatile("" : "+r"(r[i]));  // uses stay behind the wait
    v[i] = __uint_as_float(r[i]);
  }
}
__device__ __forceinline__ uint32_t ld_acquire(const unsigned int* q) {
  uint32_t v;
  asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(v) : "l"(q) : "memory");
  return v;
}
__device__ __forceinline__ void red_release(unsigned int* q, uint32_t v) {
  asm volatile("red.release.gpu.global.add.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ void st_release(unsigned int* q, uint32_t v) {
  asm volatile("st.release.gpu.global.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// GELU (erf form) on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0)   (#129 gelu2 without the sumsq)
__device__ __forceinline__ void gelu2(float& x0, float& x1) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  f2unpack(add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f))), x0, x1);
}
// 4 consecutive k of row r into the hi and lo K-major SW128 images (atom = 64 k = 128 B per row)
__device__ __forceinline__ void put_hilo(unsigned char* sm, int offh, int offl, int atom_bytes, int r, int c4, float4 v) {
  const int off = (c4 >> 4) * atom_bytes + r * 128 + ((((c4 >> 1) & 7) ^ (r & 7)) << 4) + (c4 & 1) * 8;
  const __half2 h01 = __floats2half2_rn(v.x, v.y), h23 = __floats2half2_rn(v.z, v.w);
  const float2 f01 = __half22float2(h01), f23 = __half22float2(h23);
  const __half2 l01 = __floats2half2_rn(v.x - f01.x, v.y - f01.y), l23 = __floats2half2_rn(v.z - f23.x, v.w - f23.y);
  *reinterpret_cast<uint2*>(sm + offh + off) = make_uint2(h2u(h01), h2u(h23));
  *reinterpret_cast<uint2*>(sm + offl + off) = make_uint2(h2u(l01), h2u(l23));
}

template <int TT>
__global__ void __launch_bounds__(E2_NTH, 1) e2_kernel(const E2Params p) {
  constexpr int NP = (TT + 15) / 16 * 16;  // MMA N (tokens, padded)
  constexpr int CW = NP / 4;               // columns per thread in the epilogues
  constexpr int XATOM = NP * 128;          // bytes per 64-k atom of a token-row image
  constexpr int NXL = NP / 16;             // x float4 per thread
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int slice = blockIdx.x & 3, tile = blockIdx.x >> 2, tok0 = tile * TT, b = tok0 / p.HW;
  float* s_b1 = (float*)(sm + OFF_VEC);
  float* s_gw = s_b1 + 128;
  float* s_gb = s_b1 + 256;
  float* s_nf = s_b1 + 384;
  float* s_ssp = (float*)(sm + OFF_SSP);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar1 = sb + OFF_BAR, bar2 = bar1 + 8;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 16);
  unsigned int* ctr = g_e2ctr;

  // ---- every global load up front: W1 slice (contiguous 64 KB), x tile, W2 slice (128 rows x 512 B), b1/gw/gb slices
  float4 vw1[8], vx[NXL], vw2[8], vv = make_float4(0.f, 0.f, 0.f, 0.f);
  const float4* w1s = reinterpret_cast<const float4*>(p.w1 + (size_t)slice * 128 * 128);
#pragma unroll
  for (int i = 0; i < 8; i++) vw1[i] = __ldg(w1s + tid + E2_NTH * i);
  const float4* xs = reinterpret_cast<const float4*>(p.x + (size_t)tok0 * 128);
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    vx[i] = ((f >> 5) < TT) ? __ldg(xs + f) : make_float4(0.f, 0.f, 0.f, 0.f);
  }
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    vw2[i] = __ldg(reinterpret_cast<const float4*>(p.w2 + (size_t)(f >> 5) * 512 + slice * 128) + (f & 31));
  }
  if (tid < 96) {
    const float* src = tid < 32 ? p.b1 : (tid < 64 ? p.gw : p.gb);
    vv = __ldg(reinterpret_cast<const float4*>(src + slice * 128) + (tid & 31));
  }
  if (tid == 0) {
    mbar_init(bar1, 1);
    mbar_init(bar2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  if (blockIdx.x == 0)
    for (int i = tid; i < p.B * 512; i += E2_NTH) p.gsum[i] = 0.f;
  if (tid < 96) reinterpret_cast<float4*>(s_b1)[tid] = vv;
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W1H, OFF_W1L, 16384, f >> 5, f & 31, vw1[i]);
  }
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_XH, OFF_XL, XATOM, f >> 5, f & 31, vx[i]);
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  if (blockIdx.x == 0 && tid == 0) { __threadfence(); st_release(ctr, 1u); }
  const uint32_t tmem = *s_tmem;
  // ---- GEMM1 swap-AB: D1[hid][tok] = W1h.Xh + W1h.Xl + W1l.Xh, K = 128 (cross terms first)
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int pr = 0; pr < 3; pr++) {
      const uint32_t A = (pr == 1) ? OFF_W1L : OFF_W1H;
      const uint32_t Bo = (pr == 0) ? OFF_XL : OFF_XH;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar1);
  }
  // ---- behind GEMM1: W2 slice image; the slice-0 CTA prefills its out rows with b2
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W2H, OFF_W2L, 16384, f >> 5, f & 31, vw2[i]);
  }
  fence_proxy_async();
  if (slice == 0) {
    const float4* b24 = reinterpret_cast<const float4*>(p.b2);
    float4* o4 = reinterpret_cast<float4*>(p.out + (size_t)tok0 * 128);
    for (int i = tid; i < TT * 32; i += E2_NTH) o4[i] = __ldg(b24 + (i & 31));
  }
  // ---- GEMM1 epilogue: + b1, GELU, masked per-channel sumsq; h stays in registers across the barrier
  mbar_wait(bar1, 0);
  tc_after();
  const int q = warp & 3, cq = warp >> 2, hid = 32 * q + lane;
  const uint32_t tq = tmem + ((uint32_t)(32 * q) << 16) + cq * CW;
  float h[CW];
  tmem_ld<CW>(tq, h);
  {
    const float bk = s_b1[hid];
    float ss = 0.f;
#pragma unroll
    for (int e = 0; e < CW; e += 2) {
      float x0 = h[e] + bk, x1 = h[e + 1] + bk;
      gelu2(x0, x1);
      const int t = cq * CW + e;
      if (t >= TT) x0 = 0.f;
      if (t + 1 >= TT) x1 = 0.f;
      h[e] = x0;
      h[e + 1] = x1;
      ss = fmaf(x0, x0, ss);
      ss = fmaf(x1, x1, ss);
    }
    s_ssp[cq * 128 + hid] = ss;
  }
  if (tid == 0) { while (ld_acquire(ctr) == 0u) { } }
  __syncthreads();
  if (tid < 128) atomicAdd(p.gsum + b * 512 + slice * 128 + tid, s_ssp[tid] + s_ssp[128 + tid] + s_ssp[256 + tid] + s_ssp[384 + tid]);
  __syncthreads();
  // ---- grid barrier: one arrival counter; the last departer resets the counters
  if (tid == 0) {
    __threadfence();
    red_release(ctr + 1, 1u);
    while (ld_acquire(ctr + 1) < gridDim.x) { }
    const unsigned old = atomicAdd(ctr + 2, 1u);
    if (old == gridDim.x - 1) {
      atomicExch(ctr, 0u);
      atomicExch(ctr + 1, 0u);
      atomicExch(ctr + 2, 0u);
    }
  }
  __syncthreads();
  // ---- GRN: G = sqrt(gsum), nf = G / (mean G + eps) for this slice
  {
    const float g = __fsqrt_rn(__ldcg(p.gsum + b * 512 + tid));
    const float ws = warp_sum(g);
    if (lane == 0) s_red[warp] = ws;
    __syncthreads();
    float tot = 0.f;
#pragma unroll
    for (int i = 0; i < 16; i++) tot += s_red[i];
    const float mean = __fdiv_rn(tot, 512.f);
    if ((tid >> 7) == slice) s_nf[tid & 127] = __fdiv_rn(g, mean + p.eps);
    __syncthreads();
  }
  // ---- x2 = gw*(h*nf) + gb + h, split hi/lo into the K-major token-row images (x space)
  {
    const float nfk = s_nf[hid], gwk = s_gw[hid], gbk = s_gb[hid];
    const int at = (hid >> 6) * XATOM, ch = (hid >> 3) & 7, sub = (hid & 7) * 2;
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      const float v = h[e];
      const float x2 = gwk * (v * nfk) + gbk + v;
      const __half hi = __float2half_rn(x2);
      const __half lo = __float2half_rn(x2 - __half2float(hi));
      const int off = at + t * 128 + ((ch ^ (t & 7)) << 4) + sub;
      *reinterpret_cast<__half*>(sm + OFF_XH + off) = hi;
      *reinterpret_cast<__half*>(sm + OFF_XL + off) = lo;
    }
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  // ---- GEMM2 swap-AB: D2[out][tok] = W2h.X2h (cols 128..) and W2h.X2l + W2l.X2h (cols 256..), K = 128
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int kk = 0; kk < 8; kk++) {
      const uint32_t w = (kk & 3) * 32;
      mma_issue(tmem + 128, sdesc(sb + OFF_W2H + (kk >> 2) * 16384 + w), sdesc(sb + OFF_XH + (kk >> 2) * XATOM + w), id,
                kk ? 1u : 0u);
    }
#pragma unroll
    for (int pr = 0; pr < 2; pr++) {
      const uint32_t A = pr ? OFF_W2L : OFF_W2H;
      const uint32_t Bo = pr ? OFF_XH : OFF_XL;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem + 256, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar2);
  }
  mbar_wait(bar2, 0);
  tc_after();
  {
    float m[CW], c[CW];
    tmem_ld<CW>(tq + 128, m);
    tmem_ld<CW>(tq + 256, c);
    float* ob = p.out + (size_t)tok0 * 128 + hid;  // hid = output channel here
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      if (t < TT) atomicAdd(ob + (size_t)t * 128, m[e] + c[e]);
    }
  }
  tc_before();
  __syncthreads();
  if (warp == 0) {
    tc_after();
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory");
  }
}

template <int TT>
const char* e2_launch(const E2Params& p, int N, cudaStream_t stream) {
  static bool attr_set = false;
  cudaError_t e;
  if (!attr_set) {
    e = cudaFuncSetAttribute(e2_kernel<TT>, cudaFuncAttributeMaxDynamicSharedMemorySize, E2_SMEM);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    attr_set = true;
  }
  E2Params q = p;
  void* args[] = {(void*)&q};
  e = cudaLaunchCooperativeKernel((const void*)e2_kernel<TT>, dim3(4 * (N / TT)), dim3(E2_NTH), args, (size_t)E2_SMEM, stream);
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
}  // namespace

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream) {
  const int N = B * HW;
  // e2 path: smallest token tile that divides HW and keeps 4 slices x tiles within one wave of 148 CTAs
  int tt = 0;
  const int cands[3] = {28, 49, 98};
  for (int i = 0; i < 3 && !tt; i++)
    if (HW % cands[i] == 0 && 4 * (N / cands[i]) <= 148) tt = cands[i];
  if (tt) {
    E2Params p{x, w1, b1, gw, gb, w2, b2, out, nf, B, HW, eps};
    if (tt == 28) return e2_launch<28>(p, N, stream);
    if (tt == 49) return e2_launch<49>(p, N, stream);
    return e2_launch<98>(p, N, stream);
  }
  static bool attrs_set = false;
  if (!attrs_set) {
    cudaFuncSetAttribute(k_stats, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_STATS);
    cudaFuncSetAttribute(k_main, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_MAIN);
    attrs_set = true;
  }
  const int tiles = (HW + TM - 1) / TM;
  dim3 grid(tiles, B);
  k_stats<<<grid, NT, SMEM_STATS, stream>>>(x, w1, b1, part, HW, tiles);
  k_grn<<<B, HID, 0, stream>>>(part, nf, tiles, eps);
  k_main<<<grid, NT, SMEM_MAIN, stream>>>(x, w1, b1, gw, gb, w2, b2, nf, out, HW);
  return nullptr;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream);

void run(torch::Tensor hidden_states, torch::Tensor pwconv1_weight, torch::Tensor pwconv1_bias,
         torch::Tensor grn_weight, torch::Tensor grn_bias, torch::Tensor pwconv2_weight, torch::Tensor pwconv2_bias,
         double eps, torch::Tensor output) {
  TORCH_CHECK(hidden_states.is_cuda() && hidden_states.scalar_type() == torch::kFloat32, "fp32 CUDA input");
  TORCH_CHECK(hidden_states.dim() == 4 && hidden_states.size(3) == 128, "[B,H,W,128]");
  TORCH_CHECK(pwconv1_weight.size(0) == 512 && pwconv1_weight.size(1) == 128, "W1 [512,128]");
  TORCH_CHECK(pwconv2_weight.size(0) == 128 && pwconv2_weight.size(1) == 512, "W2 [128,512]");
  for (auto* t : {&hidden_states, &pwconv1_weight, &pwconv1_bias, &grn_weight, &grn_bias, &pwconv2_weight,
                  &pwconv2_bias, &output})
    TORCH_CHECK(t->is_contiguous(), "contiguous tensors required");
  const c10::cuda::CUDAGuard guard(hidden_states.device());
  const int B = (int)hidden_states.size(0);
  const int HW = (int)(hidden_states.size(1) * hidden_states.size(2));
  const int tiles = (HW + 63) / 64;
  auto part = torch::empty({(int64_t)B * tiles * 512}, hidden_states.options());
  auto nf = torch::empty({(int64_t)B * 512}, hidden_states.options());
  const char* err = launch_grn_mlp(hidden_states.data_ptr<float>(), pwconv1_weight.data_ptr<float>(),
                                   pwconv1_bias.data_ptr<float>(), grn_weight.data_ptr<float>(), grn_bias.data_ptr<float>(),
                                   pwconv2_weight.data_ptr<float>(), pwconv2_bias.data_ptr<float>(), (float)eps,
                                   output.data_ptr<float>(), part.data_ptr<float>(), nf.data_ptr<float>(), B, HW,
                                   at::cuda::getCurrentCUDAStream());
  TORCH_CHECK(err == nullptr, err ? err : "");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "fused linear-gelu-grn-linear"); }

// 045_fused_linear_gelu_grn_linear, lineage B (r1 E2): hidden-slice fan-out for N <= 3136 tokens.
//   e2: grid = token tiles x 4 hidden slices of 128 (one wave, 1 CTA/SM, cooperative). Each CTA LDGs its fp32 slices
//       W1[slice,:], W2[:,slice] and its x tile, splits them into fp16 hi/lo SW128 smem images, runs GEMM1 swap-AB
//       (D1[hid][tok], FP16x3) into TMEM, + b1, A&S GELU, per-channel sumsq red.add into gsum[b][512] (zeroed by CTA 0
//       behind a flag), one grid counter (departure reset), GRN scale, x2 = gw*(h*nf) + gb + h split hi/lo, GEMM2
//       swap-AB (D2[out][tok], main + cross accumulators) and red.add into out (prefilled with b2 by the slice-0 CTA).
//   other shapes: r0 fp32 SIMT, three launches.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct E2Params {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; float* gsum; int B; int HW; float eps;
};

// [0] gsum-zeroed flag, [1] arrivals, [2] departures; the last departer resets all three for the next call
__device__ unsigned int g_e2ctr[4];

namespace {
// ------------------------------------------------------------------ r0 fallback (fp32 SIMT, 3 launches)
constexpr int D = 128, HID = 512, TM = 64, NC = 64, NT = 256;
constexpr int NCHUNK = HID / NC;
constexpr int LDK = D + 4;
constexpr int LDH = NC + 4;

__device__ __forceinline__ float gelu_erf(float v) {
  return v * 0.5f * (1.0f + erff(v * 0.7071067811865476f));
}

__device__ __forceinline__ void load_rows128(float* dst, const float* src, int nrows, int nvalid, int tid) {
  for (int i = tid; i < nrows * (D / 4); i += NT) {
    int r = i >> 5, k4 = (i & 31) << 2;
    float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
    if (r < nvalid) v = __ldg(reinterpret_cast<const float4*>(src + (size_t)r * D + k4));
    *reinterpret_cast<float4*>(dst + r * LDK + k4) = v;
  }
}

__device__ __forceinline__ void gemm1(float (&acc)[4][4], const float* As, const float* Ws, int tm, int tn) {
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;
#pragma unroll 4
  for (int k = 0; k < D; k += 4) {
    float4 a[4], w[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(As + (tm * 4 + i) * LDK + k);
#pragma unroll
    for (int j = 0; j < 4; ++j) w[j] = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDK + k);
#pragma unroll
    for (int i = 0; i < 4; ++i)
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        acc[i][j] = fmaf(a[i].x, w[j].x, acc[i][j]);
        acc[i][j] = fmaf(a[i].y, w[j].y, acc[i][j]);
        acc[i][j] = fmaf(a[i].z, w[j].z, acc[i][j]);
        acc[i][j] = fmaf(a[i].w, w[j].w, acc[i][j]);
      }
  }
}

__global__ void __launch_bounds__(NT) k_stats(const float* __restrict__ x, const float* __restrict__ w1,
                                              const float* __restrict__ b1, float* __restrict__ part,
                                              int HW, int tiles) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Red = Ws + NC * LDK;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  float* pout = part + ((size_t)b * tiles + tile) * HID;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
    float sq[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      float bias = __ldg(b1 + c * NC + tn + 16 * j);
      float s = 0.f;
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        if (tm * 4 + i < rows) s = fmaf(h, h, s);
      }
      s += __shfl_xor_sync(0xffffffffu, s, 16);
      sq[j] = s;
    }
    if (lane < 16) {
#pragma unroll
      for (int j = 0; j < 4; ++j) Red[warp * NC + tn + 16 * j] = sq[j];
    }
    __syncthreads();
    if (tid < NC) {
      float s = 0.f;
#pragma unroll
      for (int w = 0; w < NT / 32; ++w) s += Red[w * NC + tid];
      pout[c * NC + tid] = s;
    }
  }
}

__global__ void __launch_bounds__(HID) k_grn(const float* __restrict__ part, float* __restrict__ nf, int tiles,
                                             float eps) {
  __shared__ float red[HID / 32];
  const int b = blockIdx.x, c = threadIdx.x;
  const float* p = part + (size_t)b * tiles * HID + c;
  float s = 0.f;
  for (int t = 0; t < tiles; ++t) s += p[(size_t)t * HID];
  float g = __fsqrt_rn(s);
  float r = g;
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) r += __shfl_xor_sync(0xffffffffu, r, o);
  if ((c & 31) == 0) red[c >> 5] = r;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int w = 0; w < HID / 32; ++w) tot += red[w];
  float mean = __fdiv_rn(tot, (float)HID);
  nf[(size_t)b * HID + c] = __fdiv_rn(g, mean + eps);
}

__global__ void __launch_bounds__(NT) k_main(const float* __restrict__ x, const float* __restrict__ w1,
                                             const float* __restrict__ b1, const float* __restrict__ gw,
                                             const float* __restrict__ gb, const float* __restrict__ w2,
                                             const float* __restrict__ b2, const float* __restrict__ nf,
                                             float* __restrict__ out, int HW) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Hs = Ws + D * LDH;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  const float* nfb = nf + (size_t)b * HID;
  float acc2[4][8];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 8; ++j) acc2[i][j] = 0.f;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int n = c * NC + tn + 16 * j;
      const float bias = __ldg(b1 + n), g = __ldg(gw + n), be = __ldg(gb + n), f = __ldg(nfb + n);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        Hs[(tm * 4 + i) * LDH + tn + 16 * j] = g * (h * f) + be + h;
      }
    }
    __syncthreads();
    for (int i = tid; i < D * (NC / 4); i += NT) {
      int o = i >> 4, k4 = (i & 15) << 2;
      *reinterpret_cast<float4*>(Ws + o * LDH + k4) =
          __ldg(reinterpret_cast<const float4*>(w2 + (size_t)o * HID + c * NC + k4));
    }
    __syncthreads();
#pragma unroll 2
    for (int k = 0; k < NC; k += 4) {
      float4 a[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(Hs + (tm * 4 + i) * LDH + k);
#pragma unroll
      for (int j = 0; j < 8; ++j) {
        float4 w = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDH + k);
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          acc2[i][j] = fmaf(a[i].x, w.x, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].y, w.y, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].z, w.z, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].w, w.w, acc2[i][j]);
        }
      }
    }
  }
  float* ob = out + ((size_t)b * HW + m0) * D;
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int o = tn + 16 * j;
    const float bias = __ldg(b2 + o);
#pragma unroll
    for (int i = 0; i < 4; ++i)
      if (tm * 4 + i < rows) ob[(size_t)(tm * 4 + i) * D + o] = acc2[i][j] + bias;
  }
}

constexpr int SMEM_STATS = (TM * LDK + NC * LDK + (NT / 32) * NC) * 4;
constexpr int SMEM_MAIN = (TM * LDK + D * LDH + TM * LDH) * 4;
static_assert(D * LDH >= NC * LDK, "Ws must hold either chunk");

// ------------------------------------------------------------------ e2: hidden-slice fan-out (tcgen05 FP16x3)
constexpr int E2_NTH = 512;
constexpr int OFF_W1H = 0, OFF_W1L = 32768;      // W1 slice [128 hid][128 k] K-major SW128, hi / lo
constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
constexpr int OFF_VEC = 196608;                  // b1, gw, gb, nf slices [128] each
constexpr int OFF_SSP = 198656;                  // sumsq partials [4 column quarters][128]
constexpr int OFF_RED = 200704;                  // [16]
constexpr int OFF_BAR = 200960;                  // 2 mbarriers + TMEM slot
constexpr int E2_SMEM = 201024 + 1024;

__device__ __forceinline__ uint32_t s_addr(const void* q) { return (uint32_t)__cvta_generic_to_shared(q); }
__device__ __forceinline__ void mbar_init(uint32_t b, uint32_t n) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(b), "r"(n)); }
__device__ __forceinline__ void mbar_wait(uint32_t b, uint32_t par) {
  asm volatile("{\n.reg .pred P;\nWAIT_%=:\nmbarrier.try_wait.parity.shared::cta.b64 P, [%0], %1;\n@!P bra WAIT_%=;\n}\n" ::"r"(b), "r"(par) : "memory");
}
__device__ __forceinline__ void fence_proxy_async() { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); }
__device__ __forceinline__ void tc_before() { asm volatile("tcgen05.fence::before_thread_sync;" ::: "memory"); }
__device__ __forceinline__ void tc_after() { asm volatile("tcgen05.fence::after_thread_sync;" ::: "memory"); }
__device__ __forceinline__ uint64_t sdesc(uint32_t addr) {  // K-major SWIZZLE_128B, SBO 1024, sm100 descriptor version 1
  return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | (1ull << 46) | (2ull << 61);
}
// kind::f16: fp32 D, fp16 A/B, both K-major, M = 128
__device__ __forceinline__ uint32_t idesc_kk(int n) { return (1u << 4) | ((uint32_t)(n >> 3) << 17) | ((128u >> 4) << 24); }
__device__ __forceinline__ void mma_issue(uint32_t d, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  asm volatile("{\n.reg .pred E, A;\nelect.sync _|E, 0xffffffff;\nsetp.ne.u32 A, %4, 0;\n"
               "@E tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, A;\n}\n" ::"r"(d), "l"(a), "l"(b), "r"(id), "r"(acc) : "memory");
}
__device__ __forceinline__ void mma_commit(uint32_t bar) {
  asm volatile("{\n.reg .pred E;\nelect.sync _|E, 0xffffffff;\n"
               "@E tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}\n" ::"r"(bar) : "memory");
}
template <int N>
__device__ __forceinline__ void tmem_ld(uint32_t ta, float (&v)[N]) {
  uint32_t r[N];
#pragma unroll
  for (int i = 0; i < N / 4; i++)
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r[4 * i]), "=r"(r[4 * i + 1]), "=r"(r[4 * i + 2]), "=r"(r[4 * i + 3]) : "r"(ta + 4 * i) : "memory");
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
  for (int i = 0; i < N; i++) {
    asm volatile("" : "+r"(r[i]));  // uses stay behind the wait
    v[i] = __uint_as_float(r[i]);
  }
}
__device__ __forceinline__ uint32_t ld_acquire(const unsigned int* q) {
  uint32_t v;
  asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(v) : "l"(q) : "memory");
  return v;
}
__device__ __forceinline__ void red_release(unsigned int* q, uint32_t v) {
  asm volatile("red.release.gpu.global.add.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ void st_release(unsigned int* q, uint32_t v) {
  asm volatile("st.release.gpu.global.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// GELU (erf form) on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0)   (#129 gelu2 without the sumsq)
__device__ __forceinline__ void gelu2(float& x0, float& x1) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  f2unpack(add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f))), x0, x1);
}
// 4 consecutive k of row r into the hi and lo K-major SW128 images (atom = 64 k = 128 B per row)
__device__ __forceinline__ void put_hilo(unsigned char* sm, int offh, int offl, int atom_bytes, int r, int c4, float4 v) {
  const int off = (c4 >> 4) * atom_bytes + r * 128 + ((((c4 >> 1) & 7) ^ (r & 7)) << 4) + (c4 & 1) * 8;
  const __half2 h01 = __floats2half2_rn(v.x, v.y), h23 = __floats2half2_rn(v.z, v.w);
  const float2 f01 = __half22float2(h01), f23 = __half22float2(h23);
  const __half2 l01 = __floats2half2_rn(v.x - f01.x, v.y - f01.y), l23 = __floats2half2_rn(v.z - f23.x, v.w - f23.y);
  *reinterpret_cast<uint2*>(sm + offh + off) = make_uint2(h2u(h01), h2u(h23));
  *reinterpret_cast<uint2*>(sm + offl + off) = make_uint2(h2u(l01), h2u(l23));
}

template <int TT>
__global__ void __launch_bounds__(E2_NTH, 1) e2_kernel(const E2Params p) {
  constexpr int NP = (TT + 15) / 16 * 16;  // MMA N (tokens, padded)
  constexpr int CW = NP / 4;               // columns per thread in the epilogues
  constexpr int XATOM = NP * 128;          // bytes per 64-k atom of a token-row image
  constexpr int NXL = NP / 16;             // x float4 per thread
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int slice = blockIdx.x & 3, tile = blockIdx.x >> 2, tok0 = tile * TT, b = tok0 / p.HW;
  float* s_b1 = (float*)(sm + OFF_VEC);
  float* s_gw = s_b1 + 128;
  float* s_gb = s_b1 + 256;
  float* s_nf = s_b1 + 384;
  float* s_ssp = (float*)(sm + OFF_SSP);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar1 = sb + OFF_BAR, bar2 = bar1 + 8;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 16);
  unsigned int* ctr = g_e2ctr;

  // ---- every global load up front: W1 slice (contiguous 64 KB), x tile, W2 slice (128 rows x 512 B), b1/gw/gb slices
  float4 vw1[8], vx[NXL], vw2[8], vv = make_float4(0.f, 0.f, 0.f, 0.f);
  const float4* w1s = reinterpret_cast<const float4*>(p.w1 + (size_t)slice * 128 * 128);
#pragma unroll
  for (int i = 0; i < 8; i++) vw1[i] = __ldg(w1s + tid + E2_NTH * i);
  const float4* xs = reinterpret_cast<const float4*>(p.x + (size_t)tok0 * 128);
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    vx[i] = ((f >> 5) < TT) ? __ldg(xs + f) : make_float4(0.f, 0.f, 0.f, 0.f);
  }
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    vw2[i] = __ldg(reinterpret_cast<const float4*>(p.w2 + (size_t)(f >> 5) * 512 + slice * 128) + (f & 31));
  }
  if (tid < 96) {
    const float* src = tid < 32 ? p.b1 : (tid < 64 ? p.gw : p.gb);
    vv = __ldg(reinterpret_cast<const float4*>(src + slice * 128) + (tid & 31));
  }
  if (tid == 0) {
    mbar_init(bar1, 1);
    mbar_init(bar2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  if (blockIdx.x == 0)
    for (int i = tid; i < p.B * 512; i += E2_NTH) p.gsum[i] = 0.f;
  if (tid < 96) reinterpret_cast<float4*>(s_b1)[tid] = vv;
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W1H, OFF_W1L, 16384, f >> 5, f & 31, vw1[i]);
  }
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_XH, OFF_XL, XATOM, f >> 5, f & 31, vx[i]);
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  if (blockIdx.x == 0 && tid == 0) { __threadfence(); st_release(ctr, 1u); }
  const uint32_t tmem = *s_tmem;
  // ---- GEMM1 swap-AB: D1[hid][tok] = W1h.Xh + W1h.Xl + W1l.Xh, K = 128 (cross terms first)
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int pr = 0; pr < 3; pr++) {
      const uint32_t A = (pr == 1) ? OFF_W1L : OFF_W1H;
      const uint32_t Bo = (pr == 0) ? OFF_XL : OFF_XH;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar1);
  }
  // ---- behind GEMM1: W2 slice image; the slice-0 CTA prefills its out rows with b2
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W2H, OFF_W2L, 16384, f >> 5, f & 31, vw2[i]);
  }
  fence_proxy_async();
  if (slice == 0) {
    const float4* b24 = reinterpret_cast<const float4*>(p.b2);
    float4* o4 = reinterpret_cast<float4*>(p.out + (size_t)tok0 * 128);
    for (int i = tid; i < TT * 32; i += E2_NTH) o4[i] = __ldg(b24 + (i & 31));
  }
  // ---- GEMM1 epilogue: + b1, GELU, masked per-channel sumsq; h stays in registers across the barrier
  mbar_wait(bar1, 0);
  tc_after();
  const int q = warp & 3, cq = warp >> 2, hid = 32 * q + lane;
  const uint32_t tq = tmem + ((uint32_t)(32 * q) << 16) + cq * CW;
  float h[CW];
  tmem_ld<CW>(tq, h);
  {
    const float bk = s_b1[hid];
    float ss = 0.f;
#pragma unroll
    for (int e = 0; e < CW; e += 2) {
      float x0 = h[e] + bk, x1 = h[e + 1] + bk;
      gelu2(x0, x1);
      const int t = cq * CW + e;
      if (t >= TT) x0 = 0.f;
      if (t + 1 >= TT) x1 = 0.f;
      h[e] = x0;
      h[e + 1] = x1;
      ss = fmaf(x0, x0, ss);
      ss = fmaf(x1, x1, ss);
    }
    s_ssp[cq * 128 + hid] = ss;
  }
  if (tid == 0) { while (ld_acquire(ctr) == 0u) { } }
  __syncthreads();
  if (tid < 128) atomicAdd(p.gsum + b * 512 + slice * 128 + tid, s_ssp[tid] + s_ssp[128 + tid] + s_ssp[256 + tid] + s_ssp[384 + tid]);
  __syncthreads();
  // ---- grid barrier: one arrival counter; the last departer resets the counters
  if (tid == 0) {
    __threadfence();
    red_release(ctr + 1, 1u);
    while (ld_acquire(ctr + 1) < gridDim.x) { }
    const unsigned old = atomicAdd(ctr + 2, 1u);
    if (old == gridDim.x - 1) {
      atomicExch(ctr, 0u);
      atomicExch(ctr + 1, 0u);
      atomicExch(ctr + 2, 0u);
    }
  }
  __syncthreads();
  // ---- GRN: G = sqrt(gsum), nf = G / (mean G + eps) for this slice
  {
    const float g = __fsqrt_rn(__ldcg(p.gsum + b * 512 + tid));
    const float ws = warp_sum(g);
    if (lane == 0) s_red[warp] = ws;
    __syncthreads();
    float tot = 0.f;
#pragma unroll
    for (int i = 0; i < 16; i++) tot += s_red[i];
    const float mean = __fdiv_rn(tot, 512.f);
    if ((tid >> 7) == slice) s_nf[tid & 127] = __fdiv_rn(g, mean + p.eps);
    __syncthreads();
  }
  // ---- x2 = gw*(h*nf) + gb + h, split hi/lo into the K-major token-row images (x space)
  {
    const float nfk = s_nf[hid], gwk = s_gw[hid], gbk = s_gb[hid];
    const int at = (hid >> 6) * XATOM, ch = (hid >> 3) & 7, sub = (hid & 7) * 2;
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      const float v = h[e];
      const float x2 = gwk * (v * nfk) + gbk + v;
      const __half hi = __float2half_rn(x2);
      const __half lo = __float2half_rn(x2 - __half2float(hi));
      const int off = at + t * 128 + ((ch ^ (t & 7)) << 4) + sub;
      *reinterpret_cast<__half*>(sm + OFF_XH + off) = hi;
      *reinterpret_cast<__half*>(sm + OFF_XL + off) = lo;
    }
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  // ---- GEMM2 swap-AB: D2[out][tok] = W2h.X2h (cols 128..) and W2h.X2l + W2l.X2h (cols 256..), K = 128
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int kk = 0; kk < 8; kk++) {
      const uint32_t w = (kk & 3) * 32;
      mma_issue(tmem + 128, sdesc(sb + OFF_W2H + (kk >> 2) * 16384 + w), sdesc(sb + OFF_XH + (kk >> 2) * XATOM + w), id,
                kk ? 1u : 0u);
    }
#pragma unroll
    for (int pr = 0; pr < 2; pr++) {
      const uint32_t A = pr ? OFF_W2L : OFF_W2H;
      const uint32_t Bo = pr ? OFF_XH : OFF_XL;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem + 256, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar2);
  }
  mbar_wait(bar2, 0);
  tc_after();
  {
    float m[CW], c[CW];
    tmem_ld<CW>(tq + 128, m);
    tmem_ld<CW>(tq + 256, c);
    float* ob = p.out + (size_t)tok0 * 128 + hid;  // hid = output channel here
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      if (t < TT) atomicAdd(ob + (size_t)t * 128, m[e] + c[e]);
    }
  }
  tc_before();
  __syncthreads();
  if (warp == 0) {
    tc_after();
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory");
  }
}

template <int TT>
const char* e2_launch(const E2Params& p, int N, cudaStream_t stream) {
  static bool attr_set = false;
  cudaError_t e;
  if (!attr_set) {
    e = cudaFuncSetAttribute(e2_kernel<TT>, cudaFuncAttributeMaxDynamicSharedMemorySize, E2_SMEM);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    attr_set = true;
  }
  E2Params q = p;
  void* args[] = {(void*)&q};
  e = cudaLaunchCooperativeKernel((const void*)e2_kernel<TT>, dim3(4 * (N / TT)), dim3(E2_NTH), args, (size_t)E2_SMEM, stream);
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
}  // namespace

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream) {
  const int N = B * HW;
  // e2 path: smallest token tile that divides HW and keeps 4 slices x tiles within one wave of 148 CTAs
  int tt = 0;
  const int cands[3] = {28, 49, 98};
  for (int i = 0; i < 3 && !tt; i++)
    if (HW % cands[i] == 0 && 4 * (N / cands[i]) <= 148) tt = cands[i];
  if (tt) {
    E2Params p{x, w1, b1, gw, gb, w2, b2, out, nf, B, HW, eps};
    if (tt == 28) return e2_launch<28>(p, N, stream);
    if (tt == 49) return e2_launch<49>(p, N, stream);
    return e2_launch<98>(p, N, stream);
  }
  static bool attrs_set = false;
  if (!attrs_set) {
    cudaFuncSetAttribute(k_stats, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_STATS);
    cudaFuncSetAttribute(k_main, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_MAIN);
    attrs_set = true;
  }
  const int tiles = (HW + TM - 1) / TM;
  dim3 grid(tiles, B);
  k_stats<<<grid, NT, SMEM_STATS, stream>>>(x, w1, b1, part, HW, tiles);
  k_grn<<<B, HID, 0, stream>>>(part, nf, tiles, eps);
  k_main<<<grid, NT, SMEM_MAIN, stream>>>(x, w1, b1, gw, gb, w2, b2, nf, out, HW);
  return nullptr;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream);

void run(torch::Tensor hidden_states, torch::Tensor pwconv1_weight, torch::Tensor pwconv1_bias,
         torch::Tensor grn_weight, torch::Tensor grn_bias, torch::Tensor pwconv2_weight, torch::Tensor pwconv2_bias,
         double eps, torch::Tensor output) {
  TORCH_CHECK(hidden_states.is_cuda() && hidden_states.scalar_type() == torch::kFloat32, "fp32 CUDA input");
  TORCH_CHECK(hidden_states.dim() == 4 && hidden_states.size(3) == 128, "[B,H,W,128]");
  TORCH_CHECK(pwconv1_weight.size(0) == 512 && pwconv1_weight.size(1) == 128, "W1 [512,128]");
  TORCH_CHECK(pwconv2_weight.size(0) == 128 && pwconv2_weight.size(1) == 512, "W2 [128,512]");
  for (auto* t : {&hidden_states, &pwconv1_weight, &pwconv1_bias, &grn_weight, &grn_bias, &pwconv2_weight,
                  &pwconv2_bias, &output})
    TORCH_CHECK(t->is_contiguous(), "contiguous tensors required");
  const c10::cuda::CUDAGuard guard(hidden_states.device());
  const int B = (int)hidden_states.size(0);
  const int HW = (int)(hidden_states.size(1) * hidden_states.size(2));
  const int tiles = (HW + 63) / 64;
  auto part = torch::empty({(int64_t)B * tiles * 512}, hidden_states.options());
  auto nf = torch::empty({(int64_t)B * 512}, hidden_states.options());
  const char* err = launch_grn_mlp(hidden_states.data_ptr<float>(), pwconv1_weight.data_ptr<float>(),
                                   pwconv1_bias.data_ptr<float>(), grn_weight.data_ptr<float>(), grn_bias.data_ptr<float>(),
                                   pwconv2_weight.data_ptr<float>(), pwconv2_bias.data_ptr<float>(), (float)eps,
                                   output.data_ptr<float>(), part.data_ptr<float>(), nf.data_ptr<float>(), B, HW,
                                   at::cuda::getCurrentCUDAStream());
  TORCH_CHECK(err == nullptr, err ? err : "");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "fused linear-gelu-grn-linear"); }

// 045_fused_linear_gelu_grn_linear, lineage B (r1 E2): hidden-slice fan-out for N <= 3136 tokens.
//   e2: grid = token tiles x 4 hidden slices of 128 (one wave, 1 CTA/SM, cooperative). Each CTA LDGs its fp32 slices
//       W1[slice,:], W2[:,slice] and its x tile, splits them into fp16 hi/lo SW128 smem images, runs GEMM1 swap-AB
//       (D1[hid][tok], FP16x3) into TMEM, + b1, A&S GELU, per-channel sumsq red.add into gsum[b][512] (zeroed by CTA 0
//       behind a flag), one grid counter (departure reset), GRN scale, x2 = gw*(h*nf) + gb + h split hi/lo, GEMM2
//       swap-AB (D2[out][tok], main + cross accumulators) and red.add into out (prefilled with b2 by the slice-0 CTA).
//   other shapes: r0 fp32 SIMT, three launches.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct E2Params {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; float* gsum; int B; int HW; float eps;
};

// [0] gsum-zeroed flag, [1] arrivals, [2] departures; the last departer resets all three for the next call
__device__ unsigned int g_e2ctr[4];

namespace {
// ------------------------------------------------------------------ r0 fallback (fp32 SIMT, 3 launches)
constexpr int D = 128, HID = 512, TM = 64, NC = 64, NT = 256;
constexpr int NCHUNK = HID / NC;
constexpr int LDK = D + 4;
constexpr int LDH = NC + 4;

__device__ __forceinline__ float gelu_erf(float v) {
  return v * 0.5f * (1.0f + erff(v * 0.7071067811865476f));
}

__device__ __forceinline__ void load_rows128(float* dst, const float* src, int nrows, int nvalid, int tid) {
  for (int i = tid; i < nrows * (D / 4); i += NT) {
    int r = i >> 5, k4 = (i & 31) << 2;
    float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
    if (r < nvalid) v = __ldg(reinterpret_cast<const float4*>(src + (size_t)r * D + k4));
    *reinterpret_cast<float4*>(dst + r * LDK + k4) = v;
  }
}

__device__ __forceinline__ void gemm1(float (&acc)[4][4], const float* As, const float* Ws, int tm, int tn) {
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;
#pragma unroll 4
  for (int k = 0; k < D; k += 4) {
    float4 a[4], w[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(As + (tm * 4 + i) * LDK + k);
#pragma unroll
    for (int j = 0; j < 4; ++j) w[j] = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDK + k);
#pragma unroll
    for (int i = 0; i < 4; ++i)
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        acc[i][j] = fmaf(a[i].x, w[j].x, acc[i][j]);
        acc[i][j] = fmaf(a[i].y, w[j].y, acc[i][j]);
        acc[i][j] = fmaf(a[i].z, w[j].z, acc[i][j]);
        acc[i][j] = fmaf(a[i].w, w[j].w, acc[i][j]);
      }
  }
}

__global__ void __launch_bounds__(NT) k_stats(const float* __restrict__ x, const float* __restrict__ w1,
                                              const float* __restrict__ b1, float* __restrict__ part,
                                              int HW, int tiles) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Red = Ws + NC * LDK;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  float* pout = part + ((size_t)b * tiles + tile) * HID;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
    float sq[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      float bias = __ldg(b1 + c * NC + tn + 16 * j);
      float s = 0.f;
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        if (tm * 4 + i < rows) s = fmaf(h, h, s);
      }
      s += __shfl_xor_sync(0xffffffffu, s, 16);
      sq[j] = s;
    }
    if (lane < 16) {
#pragma unroll
      for (int j = 0; j < 4; ++j) Red[warp * NC + tn + 16 * j] = sq[j];
    }
    __syncthreads();
    if (tid < NC) {
      float s = 0.f;
#pragma unroll
      for (int w = 0; w < NT / 32; ++w) s += Red[w * NC + tid];
      pout[c * NC + tid] = s;
    }
  }
}

__global__ void __launch_bounds__(HID) k_grn(const float* __restrict__ part, float* __restrict__ nf, int tiles,
                                             float eps) {
  __shared__ float red[HID / 32];
  const int b = blockIdx.x, c = threadIdx.x;
  const float* p = part + (size_t)b * tiles * HID + c;
  float s = 0.f;
  for (int t = 0; t < tiles; ++t) s += p[(size_t)t * HID];
  float g = __fsqrt_rn(s);
  float r = g;
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) r += __shfl_xor_sync(0xffffffffu, r, o);
  if ((c & 31) == 0) red[c >> 5] = r;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int w = 0; w < HID / 32; ++w) tot += red[w];
  float mean = __fdiv_rn(tot, (float)HID);
  nf[(size_t)b * HID + c] = __fdiv_rn(g, mean + eps);
}

__global__ void __launch_bounds__(NT) k_main(const float* __restrict__ x, const float* __restrict__ w1,
                                             const float* __restrict__ b1, const float* __restrict__ gw,
                                             const float* __restrict__ gb, const float* __restrict__ w2,
                                             const float* __restrict__ b2, const float* __restrict__ nf,
                                             float* __restrict__ out, int HW) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Hs = Ws + D * LDH;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  const float* nfb = nf + (size_t)b * HID;
  float acc2[4][8];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 8; ++j) acc2[i][j] = 0.f;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int n = c * NC + tn + 16 * j;
      const float bias = __ldg(b1 + n), g = __ldg(gw + n), be = __ldg(gb + n), f = __ldg(nfb + n);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        Hs[(tm * 4 + i) * LDH + tn + 16 * j] = g * (h * f) + be + h;
      }
    }
    __syncthreads();
    for (int i = tid; i < D * (NC / 4); i += NT) {
      int o = i >> 4, k4 = (i & 15) << 2;
      *reinterpret_cast<float4*>(Ws + o * LDH + k4) =
          __ldg(reinterpret_cast<const float4*>(w2 + (size_t)o * HID + c * NC + k4));
    }
    __syncthreads();
#pragma unroll 2
    for (int k = 0; k < NC; k += 4) {
      float4 a[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(Hs + (tm * 4 + i) * LDH + k);
#pragma unroll
      for (int j = 0; j < 8; ++j) {
        float4 w = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDH + k);
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          acc2[i][j] = fmaf(a[i].x, w.x, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].y, w.y, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].z, w.z, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].w, w.w, acc2[i][j]);
        }
      }
    }
  }
  float* ob = out + ((size_t)b * HW + m0) * D;
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int o = tn + 16 * j;
    const float bias = __ldg(b2 + o);
#pragma unroll
    for (int i = 0; i < 4; ++i)
      if (tm * 4 + i < rows) ob[(size_t)(tm * 4 + i) * D + o] = acc2[i][j] + bias;
  }
}

constexpr int SMEM_STATS = (TM * LDK + NC * LDK + (NT / 32) * NC) * 4;
constexpr int SMEM_MAIN = (TM * LDK + D * LDH + TM * LDH) * 4;
static_assert(D * LDH >= NC * LDK, "Ws must hold either chunk");

// ------------------------------------------------------------------ e2: hidden-slice fan-out (tcgen05 FP16x3)
constexpr int E2_NTH = 512;
constexpr int OFF_W1H = 0, OFF_W1L = 32768;      // W1 slice [128 hid][128 k] K-major SW128, hi / lo
constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
constexpr int OFF_VEC = 196608;                  // b1, gw, gb, nf slices [128] each
constexpr int OFF_SSP = 198656;                  // sumsq partials [4 column quarters][128]
constexpr int OFF_RED = 200704;                  // [16]
constexpr int OFF_BAR = 200960;                  // 2 mbarriers + TMEM slot
constexpr int E2_SMEM = 201024 + 1024;

__device__ __forceinline__ uint32_t s_addr(const void* q) { return (uint32_t)__cvta_generic_to_shared(q); }
__device__ __forceinline__ void mbar_init(uint32_t b, uint32_t n) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(b), "r"(n)); }
__device__ __forceinline__ void mbar_wait(uint32_t b, uint32_t par) {
  asm volatile("{\n.reg .pred P;\nWAIT_%=:\nmbarrier.try_wait.parity.shared::cta.b64 P, [%0], %1;\n@!P bra WAIT_%=;\n}\n" ::"r"(b), "r"(par) : "memory");
}
__device__ __forceinline__ void fence_proxy_async() { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); }
__device__ __forceinline__ void tc_before() { asm volatile("tcgen05.fence::before_thread_sync;" ::: "memory"); }
__device__ __forceinline__ void tc_after() { asm volatile("tcgen05.fence::after_thread_sync;" ::: "memory"); }
__device__ __forceinline__ uint64_t sdesc(uint32_t addr) {  // K-major SWIZZLE_128B, SBO 1024, sm100 descriptor version 1
  return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | (1ull << 46) | (2ull << 61);
}
// kind::f16: fp32 D, fp16 A/B, both K-major, M = 128
__device__ __forceinline__ uint32_t idesc_kk(int n) { return (1u << 4) | ((uint32_t)(n >> 3) << 17) | ((128u >> 4) << 24); }
__device__ __forceinline__ void mma_issue(uint32_t d, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  asm volatile("{\n.reg .pred E, A;\nelect.sync _|E, 0xffffffff;\nsetp.ne.u32 A, %4, 0;\n"
               "@E tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, A;\n}\n" ::"r"(d), "l"(a), "l"(b), "r"(id), "r"(acc) : "memory");
}
__device__ __forceinline__ void mma_commit(uint32_t bar) {
  asm volatile("{\n.reg .pred E;\nelect.sync _|E, 0xffffffff;\n"
               "@E tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}\n" ::"r"(bar) : "memory");
}
template <int N>
__device__ __forceinline__ void tmem_ld(uint32_t ta, float (&v)[N]) {
  uint32_t r[N];
#pragma unroll
  for (int i = 0; i < N / 4; i++)
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r[4 * i]), "=r"(r[4 * i + 1]), "=r"(r[4 * i + 2]), "=r"(r[4 * i + 3]) : "r"(ta + 4 * i) : "memory");
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
  for (int i = 0; i < N; i++) {
    asm volatile("" : "+r"(r[i]));  // uses stay behind the wait
    v[i] = __uint_as_float(r[i]);
  }
}
__device__ __forceinline__ uint32_t ld_acquire(const unsigned int* q) {
  uint32_t v;
  asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(v) : "l"(q) : "memory");
  return v;
}
__device__ __forceinline__ void red_release(unsigned int* q, uint32_t v) {
  asm volatile("red.release.gpu.global.add.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ void st_release(unsigned int* q, uint32_t v) {
  asm volatile("st.release.gpu.global.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// GELU (erf form) on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0)   (#129 gelu2 without the sumsq)
__device__ __forceinline__ void gelu2(float& x0, float& x1) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  f2unpack(add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f))), x0, x1);
}
// 4 consecutive k of row r into the hi and lo K-major SW128 images (atom = 64 k = 128 B per row)
__device__ __forceinline__ void put_hilo(unsigned char* sm, int offh, int offl, int atom_bytes, int r, int c4, float4 v) {
  const int off = (c4 >> 4) * atom_bytes + r * 128 + ((((c4 >> 1) & 7) ^ (r & 7)) << 4) + (c4 & 1) * 8;
  const __half2 h01 = __floats2half2_rn(v.x, v.y), h23 = __floats2half2_rn(v.z, v.w);
  const float2 f01 = __half22float2(h01), f23 = __half22float2(h23);
  const __half2 l01 = __floats2half2_rn(v.x - f01.x, v.y - f01.y), l23 = __floats2half2_rn(v.z - f23.x, v.w - f23.y);
  *reinterpret_cast<uint2*>(sm + offh + off) = make_uint2(h2u(h01), h2u(h23));
  *reinterpret_cast<uint2*>(sm + offl + off) = make_uint2(h2u(l01), h2u(l23));
}

template <int TT>
__global__ void __launch_bounds__(E2_NTH, 1) e2_kernel(const E2Params p) {
  constexpr int NP = (TT + 15) / 16 * 16;  // MMA N (tokens, padded)
  constexpr int CW = NP / 4;               // columns per thread in the epilogues
  constexpr int XATOM = NP * 128;          // bytes per 64-k atom of a token-row image
  constexpr int NXL = NP / 16;             // x float4 per thread
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int slice = blockIdx.x & 3, tile = blockIdx.x >> 2, tok0 = tile * TT, b = tok0 / p.HW;
  float* s_b1 = (float*)(sm + OFF_VEC);
  float* s_gw = s_b1 + 128;
  float* s_gb = s_b1 + 256;
  float* s_nf = s_b1 + 384;
  float* s_ssp = (float*)(sm + OFF_SSP);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar1 = sb + OFF_BAR, bar2 = bar1 + 8;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 16);
  unsigned int* ctr = g_e2ctr;

  // ---- every global load up front: W1 slice (contiguous 64 KB), x tile, W2 slice (128 rows x 512 B), b1/gw/gb slices
  float4 vw1[8], vx[NXL], vw2[8], vv = make_float4(0.f, 0.f, 0.f, 0.f);
  const float4* w1s = reinterpret_cast<const float4*>(p.w1 + (size_t)slice * 128 * 128);
#pragma unroll
  for (int i = 0; i < 8; i++) vw1[i] = __ldg(w1s + tid + E2_NTH * i);
  const float4* xs = reinterpret_cast<const float4*>(p.x + (size_t)tok0 * 128);
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    vx[i] = ((f >> 5) < TT) ? __ldg(xs + f) : make_float4(0.f, 0.f, 0.f, 0.f);
  }
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    vw2[i] = __ldg(reinterpret_cast<const float4*>(p.w2 + (size_t)(f >> 5) * 512 + slice * 128) + (f & 31));
  }
  if (tid < 96) {
    const float* src = tid < 32 ? p.b1 : (tid < 64 ? p.gw : p.gb);
    vv = __ldg(reinterpret_cast<const float4*>(src + slice * 128) + (tid & 31));
  }
  if (tid == 0) {
    mbar_init(bar1, 1);
    mbar_init(bar2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  if (blockIdx.x == 0)
    for (int i = tid; i < p.B * 512; i += E2_NTH) p.gsum[i] = 0.f;
  if (tid < 96) reinterpret_cast<float4*>(s_b1)[tid] = vv;
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W1H, OFF_W1L, 16384, f >> 5, f & 31, vw1[i]);
  }
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_XH, OFF_XL, XATOM, f >> 5, f & 31, vx[i]);
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  if (blockIdx.x == 0 && tid == 0) { __threadfence(); st_release(ctr, 1u); }
  const uint32_t tmem = *s_tmem;
  // ---- GEMM1 swap-AB: D1[hid][tok] = W1h.Xh + W1h.Xl + W1l.Xh, K = 128 (cross terms first)
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int pr = 0; pr < 3; pr++) {
      const uint32_t A = (pr == 1) ? OFF_W1L : OFF_W1H;
      const uint32_t Bo = (pr == 0) ? OFF_XL : OFF_XH;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar1);
  }
  // ---- behind GEMM1: W2 slice image; the slice-0 CTA prefills its out rows with b2
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W2H, OFF_W2L, 16384, f >> 5, f & 31, vw2[i]);
  }
  fence_proxy_async();
  if (slice == 0) {
    const float4* b24 = reinterpret_cast<const float4*>(p.b2);
    float4* o4 = reinterpret_cast<float4*>(p.out + (size_t)tok0 * 128);
    for (int i = tid; i < TT * 32; i += E2_NTH) o4[i] = __ldg(b24 + (i & 31));
  }
  // ---- GEMM1 epilogue: + b1, GELU, masked per-channel sumsq; h stays in registers across the barrier
  mbar_wait(bar1, 0);
  tc_after();
  const int q = warp & 3, cq = warp >> 2, hid = 32 * q + lane;
  const uint32_t tq = tmem + ((uint32_t)(32 * q) << 16) + cq * CW;
  float h[CW];
  tmem_ld<CW>(tq, h);
  {
    const float bk = s_b1[hid];
    float ss = 0.f;
#pragma unroll
    for (int e = 0; e < CW; e += 2) {
      float x0 = h[e] + bk, x1 = h[e + 1] + bk;
      gelu2(x0, x1);
      const int t = cq * CW + e;
      if (t >= TT) x0 = 0.f;
      if (t + 1 >= TT) x1 = 0.f;
      h[e] = x0;
      h[e + 1] = x1;
      ss = fmaf(x0, x0, ss);
      ss = fmaf(x1, x1, ss);
    }
    s_ssp[cq * 128 + hid] = ss;
  }
  if (tid == 0) { while (ld_acquire(ctr) == 0u) { } }
  __syncthreads();
  if (tid < 128) atomicAdd(p.gsum + b * 512 + slice * 128 + tid, s_ssp[tid] + s_ssp[128 + tid] + s_ssp[256 + tid] + s_ssp[384 + tid]);
  __syncthreads();
  // ---- grid barrier: one arrival counter; the last departer resets the counters
  if (tid == 0) {
    __threadfence();
    red_release(ctr + 1, 1u);
    while (ld_acquire(ctr + 1) < gridDim.x) { }
    const unsigned old = atomicAdd(ctr + 2, 1u);
    if (old == gridDim.x - 1) {
      atomicExch(ctr, 0u);
      atomicExch(ctr + 1, 0u);
      atomicExch(ctr + 2, 0u);
    }
  }
  __syncthreads();
  // ---- GRN: G = sqrt(gsum), nf = G / (mean G + eps) for this slice
  {
    const float g = __fsqrt_rn(__ldcg(p.gsum + b * 512 + tid));
    const float ws = warp_sum(g);
    if (lane == 0) s_red[warp] = ws;
    __syncthreads();
    float tot = 0.f;
#pragma unroll
    for (int i = 0; i < 16; i++) tot += s_red[i];
    const float mean = __fdiv_rn(tot, 512.f);
    if ((tid >> 7) == slice) s_nf[tid & 127] = __fdiv_rn(g, mean + p.eps);
    __syncthreads();
  }
  // ---- x2 = gw*(h*nf) + gb + h, split hi/lo into the K-major token-row images (x space)
  {
    const float nfk = s_nf[hid], gwk = s_gw[hid], gbk = s_gb[hid];
    const int at = (hid >> 6) * XATOM, ch = (hid >> 3) & 7, sub = (hid & 7) * 2;
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      const float v = h[e];
      const float x2 = gwk * (v * nfk) + gbk + v;
      const __half hi = __float2half_rn(x2);
      const __half lo = __float2half_rn(x2 - __half2float(hi));
      const int off = at + t * 128 + ((ch ^ (t & 7)) << 4) + sub;
      *reinterpret_cast<__half*>(sm + OFF_XH + off) = hi;
      *reinterpret_cast<__half*>(sm + OFF_XL + off) = lo;
    }
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  // ---- GEMM2 swap-AB: D2[out][tok] = W2h.X2h (cols 128..) and W2h.X2l + W2l.X2h (cols 256..), K = 128
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int kk = 0; kk < 8; kk++) {
      const uint32_t w = (kk & 3) * 32;
      mma_issue(tmem + 128, sdesc(sb + OFF_W2H + (kk >> 2) * 16384 + w), sdesc(sb + OFF_XH + (kk >> 2) * XATOM + w), id,
                kk ? 1u : 0u);
    }
#pragma unroll
    for (int pr = 0; pr < 2; pr++) {
      const uint32_t A = pr ? OFF_W2L : OFF_W2H;
      const uint32_t Bo = pr ? OFF_XH : OFF_XL;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem + 256, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar2);
  }
  mbar_wait(bar2, 0);
  tc_after();
  {
    float m[CW], c[CW];
    tmem_ld<CW>(tq + 128, m);
    tmem_ld<CW>(tq + 256, c);
    float* ob = p.out + (size_t)tok0 * 128 + hid;  // hid = output channel here
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      if (t < TT) atomicAdd(ob + (size_t)t * 128, m[e] + c[e]);
    }
  }
  tc_before();
  __syncthreads();
  if (warp == 0) {
    tc_after();
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory");
  }
}

template <int TT>
const char* e2_launch(const E2Params& p, int N, cudaStream_t stream) {
  static bool attr_set = false;
  cudaError_t e;
  if (!attr_set) {
    e = cudaFuncSetAttribute(e2_kernel<TT>, cudaFuncAttributeMaxDynamicSharedMemorySize, E2_SMEM);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    attr_set = true;
  }
  E2Params q = p;
  void* args[] = {(void*)&q};
  e = cudaLaunchCooperativeKernel((const void*)e2_kernel<TT>, dim3(4 * (N / TT)), dim3(E2_NTH), args, (size_t)E2_SMEM, stream);
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
}  // namespace

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream) {
  const int N = B * HW;
  // e2 path: smallest token tile that divides HW and keeps 4 slices x tiles within one wave of 148 CTAs
  int tt = 0;
  const int cands[3] = {28, 49, 98};
  for (int i = 0; i < 3 && !tt; i++)
    if (HW % cands[i] == 0 && 4 * (N / cands[i]) <= 148) tt = cands[i];
  if (tt) {
    E2Params p{x, w1, b1, gw, gb, w2, b2, out, nf, B, HW, eps};
    if (tt == 28) return e2_launch<28>(p, N, stream);
    if (tt == 49) return e2_launch<49>(p, N, stream);
    return e2_launch<98>(p, N, stream);
  }
  static bool attrs_set = false;
  if (!attrs_set) {
    cudaFuncSetAttribute(k_stats, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_STATS);
    cudaFuncSetAttribute(k_main, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_MAIN);
    attrs_set = true;
  }
  const int tiles = (HW + TM - 1) / TM;
  dim3 grid(tiles, B);
  k_stats<<<grid, NT, SMEM_STATS, stream>>>(x, w1, b1, part, HW, tiles);
  k_grn<<<B, HID, 0, stream>>>(part, nf, tiles, eps);
  k_main<<<grid, NT, SMEM_MAIN, stream>>>(x, w1, b1, gw, gb, w2, b2, nf, out, HW);
  return nullptr;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream);

void run(torch::Tensor hidden_states, torch::Tensor pwconv1_weight, torch::Tensor pwconv1_bias,
         torch::Tensor grn_weight, torch::Tensor grn_bias, torch::Tensor pwconv2_weight, torch::Tensor pwconv2_bias,
         double eps, torch::Tensor output) {
  TORCH_CHECK(hidden_states.is_cuda() && hidden_states.scalar_type() == torch::kFloat32, "fp32 CUDA input");
  TORCH_CHECK(hidden_states.dim() == 4 && hidden_states.size(3) == 128, "[B,H,W,128]");
  TORCH_CHECK(pwconv1_weight.size(0) == 512 && pwconv1_weight.size(1) == 128, "W1 [512,128]");
  TORCH_CHECK(pwconv2_weight.size(0) == 128 && pwconv2_weight.size(1) == 512, "W2 [128,512]");
  for (auto* t : {&hidden_states, &pwconv1_weight, &pwconv1_bias, &grn_weight, &grn_bias, &pwconv2_weight,
                  &pwconv2_bias, &output})
    TORCH_CHECK(t->is_contiguous(), "contiguous tensors required");
  const c10::cuda::CUDAGuard guard(hidden_states.device());
  const int B = (int)hidden_states.size(0);
  const int HW = (int)(hidden_states.size(1) * hidden_states.size(2));
  const int tiles = (HW + 63) / 64;
  auto part = torch::empty({(int64_t)B * tiles * 512}, hidden_states.options());
  auto nf = torch::empty({(int64_t)B * 512}, hidden_states.options());
  const char* err = launch_grn_mlp(hidden_states.data_ptr<float>(), pwconv1_weight.data_ptr<float>(),
                                   pwconv1_bias.data_ptr<float>(), grn_weight.data_ptr<float>(), grn_bias.data_ptr<float>(),
                                   pwconv2_weight.data_ptr<float>(), pwconv2_bias.data_ptr<float>(), (float)eps,
                                   output.data_ptr<float>(), part.data_ptr<float>(), nf.data_ptr<float>(), B, HW,
                                   at::cuda::getCurrentCUDAStream());
  TORCH_CHECK(err == nullptr, err ? err : "");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "fused linear-gelu-grn-linear"); }

// 045_fused_linear_gelu_grn_linear, lineage B (r1 E2): hidden-slice fan-out for N <= 3136 tokens.
//   e2: grid = token tiles x 4 hidden slices of 128 (one wave, 1 CTA/SM, cooperative). Each CTA LDGs its fp32 slices
//       W1[slice,:], W2[:,slice] and its x tile, splits them into fp16 hi/lo SW128 smem images, runs GEMM1 swap-AB
//       (D1[hid][tok], FP16x3) into TMEM, + b1, A&S GELU, per-channel sumsq red.add into gsum[b][512] (zeroed by CTA 0
//       behind a flag), one grid counter (departure reset), GRN scale, x2 = gw*(h*nf) + gb + h split hi/lo, GEMM2
//       swap-AB (D2[out][tok], main + cross accumulators) and red.add into out (prefilled with b2 by the slice-0 CTA).
//   other shapes: r0 fp32 SIMT, three launches.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct E2Params {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; float* gsum; int B; int HW; float eps;
};

// [0] gsum-zeroed flag, [1] arrivals, [2] departures; the last departer resets all three for the next call
__device__ unsigned int g_e2ctr[4];

namespace {
// ------------------------------------------------------------------ r0 fallback (fp32 SIMT, 3 launches)
constexpr int D = 128, HID = 512, TM = 64, NC = 64, NT = 256;
constexpr int NCHUNK = HID / NC;
constexpr int LDK = D + 4;
constexpr int LDH = NC + 4;

__device__ __forceinline__ float gelu_erf(float v) {
  return v * 0.5f * (1.0f + erff(v * 0.7071067811865476f));
}

__device__ __forceinline__ void load_rows128(float* dst, const float* src, int nrows, int nvalid, int tid) {
  for (int i = tid; i < nrows * (D / 4); i += NT) {
    int r = i >> 5, k4 = (i & 31) << 2;
    float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
    if (r < nvalid) v = __ldg(reinterpret_cast<const float4*>(src + (size_t)r * D + k4));
    *reinterpret_cast<float4*>(dst + r * LDK + k4) = v;
  }
}

__device__ __forceinline__ void gemm1(float (&acc)[4][4], const float* As, const float* Ws, int tm, int tn) {
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;
#pragma unroll 4
  for (int k = 0; k < D; k += 4) {
    float4 a[4], w[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(As + (tm * 4 + i) * LDK + k);
#pragma unroll
    for (int j = 0; j < 4; ++j) w[j] = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDK + k);
#pragma unroll
    for (int i = 0; i < 4; ++i)
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        acc[i][j] = fmaf(a[i].x, w[j].x, acc[i][j]);
        acc[i][j] = fmaf(a[i].y, w[j].y, acc[i][j]);
        acc[i][j] = fmaf(a[i].z, w[j].z, acc[i][j]);
        acc[i][j] = fmaf(a[i].w, w[j].w, acc[i][j]);
      }
  }
}

__global__ void __launch_bounds__(NT) k_stats(const float* __restrict__ x, const float* __restrict__ w1,
                                              const float* __restrict__ b1, float* __restrict__ part,
                                              int HW, int tiles) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Red = Ws + NC * LDK;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  float* pout = part + ((size_t)b * tiles + tile) * HID;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
    float sq[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      float bias = __ldg(b1 + c * NC + tn + 16 * j);
      float s = 0.f;
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        if (tm * 4 + i < rows) s = fmaf(h, h, s);
      }
      s += __shfl_xor_sync(0xffffffffu, s, 16);
      sq[j] = s;
    }
    if (lane < 16) {
#pragma unroll
      for (int j = 0; j < 4; ++j) Red[warp * NC + tn + 16 * j] = sq[j];
    }
    __syncthreads();
    if (tid < NC) {
      float s = 0.f;
#pragma unroll
      for (int w = 0; w < NT / 32; ++w) s += Red[w * NC + tid];
      pout[c * NC + tid] = s;
    }
  }
}

__global__ void __launch_bounds__(HID) k_grn(const float* __restrict__ part, float* __restrict__ nf, int tiles,
                                             float eps) {
  __shared__ float red[HID / 32];
  const int b = blockIdx.x, c = threadIdx.x;
  const float* p = part + (size_t)b * tiles * HID + c;
  float s = 0.f;
  for (int t = 0; t < tiles; ++t) s += p[(size_t)t * HID];
  float g = __fsqrt_rn(s);
  float r = g;
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) r += __shfl_xor_sync(0xffffffffu, r, o);
  if ((c & 31) == 0) red[c >> 5] = r;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int w = 0; w < HID / 32; ++w) tot += red[w];
  float mean = __fdiv_rn(tot, (float)HID);
  nf[(size_t)b * HID + c] = __fdiv_rn(g, mean + eps);
}

__global__ void __launch_bounds__(NT) k_main(const float* __restrict__ x, const float* __restrict__ w1,
                                             const float* __restrict__ b1, const float* __restrict__ gw,
                                             const float* __restrict__ gb, const float* __restrict__ w2,
                                             const float* __restrict__ b2, const float* __restrict__ nf,
                                             float* __restrict__ out, int HW) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Hs = Ws + D * LDH;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  const float* nfb = nf + (size_t)b * HID;
  float acc2[4][8];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 8; ++j) acc2[i][j] = 0.f;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int n = c * NC + tn + 16 * j;
      const float bias = __ldg(b1 + n), g = __ldg(gw + n), be = __ldg(gb + n), f = __ldg(nfb + n);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        Hs[(tm * 4 + i) * LDH + tn + 16 * j] = g * (h * f) + be + h;
      }
    }
    __syncthreads();
    for (int i = tid; i < D * (NC / 4); i += NT) {
      int o = i >> 4, k4 = (i & 15) << 2;
      *reinterpret_cast<float4*>(Ws + o * LDH + k4) =
          __ldg(reinterpret_cast<const float4*>(w2 + (size_t)o * HID + c * NC + k4));
    }
    __syncthreads();
#pragma unroll 2
    for (int k = 0; k < NC; k += 4) {
      float4 a[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(Hs + (tm * 4 + i) * LDH + k);
#pragma unroll
      for (int j = 0; j < 8; ++j) {
        float4 w = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDH + k);
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          acc2[i][j] = fmaf(a[i].x, w.x, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].y, w.y, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].z, w.z, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].w, w.w, acc2[i][j]);
        }
      }
    }
  }
  float* ob = out + ((size_t)b * HW + m0) * D;
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int o = tn + 16 * j;
    const float bias = __ldg(b2 + o);
#pragma unroll
    for (int i = 0; i < 4; ++i)
      if (tm * 4 + i < rows) ob[(size_t)(tm * 4 + i) * D + o] = acc2[i][j] + bias;
  }
}

constexpr int SMEM_STATS = (TM * LDK + NC * LDK + (NT / 32) * NC) * 4;
constexpr int SMEM_MAIN = (TM * LDK + D * LDH + TM * LDH) * 4;
static_assert(D * LDH >= NC * LDK, "Ws must hold either chunk");

// ------------------------------------------------------------------ e2: hidden-slice fan-out (tcgen05 FP16x3)
constexpr int E2_NTH = 512;
constexpr int OFF_W1H = 0, OFF_W1L = 32768;      // W1 slice [128 hid][128 k] K-major SW128, hi / lo
constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
constexpr int OFF_VEC = 196608;                  // b1, gw, gb, nf slices [128] each
constexpr int OFF_SSP = 198656;                  // sumsq partials [4 column quarters][128]
constexpr int OFF_RED = 200704;                  // [16]
constexpr int OFF_BAR = 200960;                  // 2 mbarriers + TMEM slot
constexpr int E2_SMEM = 201024 + 1024;

__device__ __forceinline__ uint32_t s_addr(const void* q) { return (uint32_t)__cvta_generic_to_shared(q); }
__device__ __forceinline__ void mbar_init(uint32_t b, uint32_t n) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(b), "r"(n)); }
__device__ __forceinline__ void mbar_wait(uint32_t b, uint32_t par) {
  asm volatile("{\n.reg .pred P;\nWAIT_%=:\nmbarrier.try_wait.parity.shared::cta.b64 P, [%0], %1;\n@!P bra WAIT_%=;\n}\n" ::"r"(b), "r"(par) : "memory");
}
__device__ __forceinline__ void fence_proxy_async() { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); }
__device__ __forceinline__ void tc_before() { asm volatile("tcgen05.fence::before_thread_sync;" ::: "memory"); }
__device__ __forceinline__ void tc_after() { asm volatile("tcgen05.fence::after_thread_sync;" ::: "memory"); }
__device__ __forceinline__ uint64_t sdesc(uint32_t addr) {  // K-major SWIZZLE_128B, SBO 1024, sm100 descriptor version 1
  return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | (1ull << 46) | (2ull << 61);
}
// kind::f16: fp32 D, fp16 A/B, both K-major, M = 128
__device__ __forceinline__ uint32_t idesc_kk(int n) { return (1u << 4) | ((uint32_t)(n >> 3) << 17) | ((128u >> 4) << 24); }
__device__ __forceinline__ void mma_issue(uint32_t d, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  asm volatile("{\n.reg .pred E, A;\nelect.sync _|E, 0xffffffff;\nsetp.ne.u32 A, %4, 0;\n"
               "@E tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, A;\n}\n" ::"r"(d), "l"(a), "l"(b), "r"(id), "r"(acc) : "memory");
}
__device__ __forceinline__ void mma_commit(uint32_t bar) {
  asm volatile("{\n.reg .pred E;\nelect.sync _|E, 0xffffffff;\n"
               "@E tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}\n" ::"r"(bar) : "memory");
}
template <int N>
__device__ __forceinline__ void tmem_ld(uint32_t ta, float (&v)[N]) {
  uint32_t r[N];
#pragma unroll
  for (int i = 0; i < N / 4; i++)
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r[4 * i]), "=r"(r[4 * i + 1]), "=r"(r[4 * i + 2]), "=r"(r[4 * i + 3]) : "r"(ta + 4 * i) : "memory");
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
  for (int i = 0; i < N; i++) {
    asm volatile("" : "+r"(r[i]));  // uses stay behind the wait
    v[i] = __uint_as_float(r[i]);
  }
}
__device__ __forceinline__ uint32_t ld_acquire(const unsigned int* q) {
  uint32_t v;
  asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(v) : "l"(q) : "memory");
  return v;
}
__device__ __forceinline__ void red_release(unsigned int* q, uint32_t v) {
  asm volatile("red.release.gpu.global.add.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ void st_release(unsigned int* q, uint32_t v) {
  asm volatile("st.release.gpu.global.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// GELU (erf form) on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0)   (#129 gelu2 without the sumsq)
__device__ __forceinline__ void gelu2(float& x0, float& x1) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  f2unpack(add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f))), x0, x1);
}
// 4 consecutive k of row r into the hi and lo K-major SW128 images (atom = 64 k = 128 B per row)
__device__ __forceinline__ void put_hilo(unsigned char* sm, int offh, int offl, int atom_bytes, int r, int c4, float4 v) {
  const int off = (c4 >> 4) * atom_bytes + r * 128 + ((((c4 >> 1) & 7) ^ (r & 7)) << 4) + (c4 & 1) * 8;
  const __half2 h01 = __floats2half2_rn(v.x, v.y), h23 = __floats2half2_rn(v.z, v.w);
  const float2 f01 = __half22float2(h01), f23 = __half22float2(h23);
  const __half2 l01 = __floats2half2_rn(v.x - f01.x, v.y - f01.y), l23 = __floats2half2_rn(v.z - f23.x, v.w - f23.y);
  *reinterpret_cast<uint2*>(sm + offh + off) = make_uint2(h2u(h01), h2u(h23));
  *reinterpret_cast<uint2*>(sm + offl + off) = make_uint2(h2u(l01), h2u(l23));
}

template <int TT>
__global__ void __launch_bounds__(E2_NTH, 1) e2_kernel(const E2Params p) {
  constexpr int NP = (TT + 15) / 16 * 16;  // MMA N (tokens, padded)
  constexpr int CW = NP / 4;               // columns per thread in the epilogues
  constexpr int XATOM = NP * 128;          // bytes per 64-k atom of a token-row image
  constexpr int NXL = NP / 16;             // x float4 per thread
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int slice = blockIdx.x & 3, tile = blockIdx.x >> 2, tok0 = tile * TT, b = tok0 / p.HW;
  float* s_b1 = (float*)(sm + OFF_VEC);
  float* s_gw = s_b1 + 128;
  float* s_gb = s_b1 + 256;
  float* s_nf = s_b1 + 384;
  float* s_ssp = (float*)(sm + OFF_SSP);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar1 = sb + OFF_BAR, bar2 = bar1 + 8;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 16);
  unsigned int* ctr = g_e2ctr;

  // ---- every global load up front: W1 slice (contiguous 64 KB), x tile, W2 slice (128 rows x 512 B), b1/gw/gb slices
  float4 vw1[8], vx[NXL], vw2[8], vv = make_float4(0.f, 0.f, 0.f, 0.f);
  const float4* w1s = reinterpret_cast<const float4*>(p.w1 + (size_t)slice * 128 * 128);
#pragma unroll
  for (int i = 0; i < 8; i++) vw1[i] = __ldg(w1s + tid + E2_NTH * i);
  const float4* xs = reinterpret_cast<const float4*>(p.x + (size_t)tok0 * 128);
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    vx[i] = ((f >> 5) < TT) ? __ldg(xs + f) : make_float4(0.f, 0.f, 0.f, 0.f);
  }
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    vw2[i] = __ldg(reinterpret_cast<const float4*>(p.w2 + (size_t)(f >> 5) * 512 + slice * 128) + (f & 31));
  }
  if (tid < 96) {
    const float* src = tid < 32 ? p.b1 : (tid < 64 ? p.gw : p.gb);
    vv = __ldg(reinterpret_cast<const float4*>(src + slice * 128) + (tid & 31));
  }
  if (tid == 0) {
    mbar_init(bar1, 1);
    mbar_init(bar2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  if (blockIdx.x == 0)
    for (int i = tid; i < p.B * 512; i += E2_NTH) p.gsum[i] = 0.f;
  if (tid < 96) reinterpret_cast<float4*>(s_b1)[tid] = vv;
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W1H, OFF_W1L, 16384, f >> 5, f & 31, vw1[i]);
  }
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_XH, OFF_XL, XATOM, f >> 5, f & 31, vx[i]);
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  if (blockIdx.x == 0 && tid == 0) { __threadfence(); st_release(ctr, 1u); }
  const uint32_t tmem = *s_tmem;
  // ---- GEMM1 swap-AB: D1[hid][tok] = W1h.Xh + W1h.Xl + W1l.Xh, K = 128 (cross terms first)
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int pr = 0; pr < 3; pr++) {
      const uint32_t A = (pr == 1) ? OFF_W1L : OFF_W1H;
      const uint32_t Bo = (pr == 0) ? OFF_XL : OFF_XH;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar1);
  }
  // ---- behind GEMM1: W2 slice image; the slice-0 CTA prefills its out rows with b2
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W2H, OFF_W2L, 16384, f >> 5, f & 31, vw2[i]);
  }
  fence_proxy_async();
  if (slice == 0) {
    const float4* b24 = reinterpret_cast<const float4*>(p.b2);
    float4* o4 = reinterpret_cast<float4*>(p.out + (size_t)tok0 * 128);
    for (int i = tid; i < TT * 32; i += E2_NTH) o4[i] = __ldg(b24 + (i & 31));
  }
  // ---- GEMM1 epilogue: + b1, GELU, masked per-channel sumsq; h stays in registers across the barrier
  mbar_wait(bar1, 0);
  tc_after();
  const int q = warp & 3, cq = warp >> 2, hid = 32 * q + lane;
  const uint32_t tq = tmem + ((uint32_t)(32 * q) << 16) + cq * CW;
  float h[CW];
  tmem_ld<CW>(tq, h);
  {
    const float bk = s_b1[hid];
    float ss = 0.f;
#pragma unroll
    for (int e = 0; e < CW; e += 2) {
      float x0 = h[e] + bk, x1 = h[e + 1] + bk;
      gelu2(x0, x1);
      const int t = cq * CW + e;
      if (t >= TT) x0 = 0.f;
      if (t + 1 >= TT) x1 = 0.f;
      h[e] = x0;
      h[e + 1] = x1;
      ss = fmaf(x0, x0, ss);
      ss = fmaf(x1, x1, ss);
    }
    s_ssp[cq * 128 + hid] = ss;
  }
  if (tid == 0) { while (ld_acquire(ctr) == 0u) { } }
  __syncthreads();
  if (tid < 128) atomicAdd(p.gsum + b * 512 + slice * 128 + tid, s_ssp[tid] + s_ssp[128 + tid] + s_ssp[256 + tid] + s_ssp[384 + tid]);
  __syncthreads();
  // ---- grid barrier: one arrival counter; the last departer resets the counters
  if (tid == 0) {
    __threadfence();
    red_release(ctr + 1, 1u);
    while (ld_acquire(ctr + 1) < gridDim.x) { }
    const unsigned old = atomicAdd(ctr + 2, 1u);
    if (old == gridDim.x - 1) {
      atomicExch(ctr, 0u);
      atomicExch(ctr + 1, 0u);
      atomicExch(ctr + 2, 0u);
    }
  }
  __syncthreads();
  // ---- GRN: G = sqrt(gsum), nf = G / (mean G + eps) for this slice
  {
    const float g = __fsqrt_rn(__ldcg(p.gsum + b * 512 + tid));
    const float ws = warp_sum(g);
    if (lane == 0) s_red[warp] = ws;
    __syncthreads();
    float tot = 0.f;
#pragma unroll
    for (int i = 0; i < 16; i++) tot += s_red[i];
    const float mean = __fdiv_rn(tot, 512.f);
    if ((tid >> 7) == slice) s_nf[tid & 127] = __fdiv_rn(g, mean + p.eps);
    __syncthreads();
  }
  // ---- x2 = gw*(h*nf) + gb + h, split hi/lo into the K-major token-row images (x space)
  {
    const float nfk = s_nf[hid], gwk = s_gw[hid], gbk = s_gb[hid];
    const int at = (hid >> 6) * XATOM, ch = (hid >> 3) & 7, sub = (hid & 7) * 2;
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      const float v = h[e];
      const float x2 = gwk * (v * nfk) + gbk + v;
      const __half hi = __float2half_rn(x2);
      const __half lo = __float2half_rn(x2 - __half2float(hi));
      const int off = at + t * 128 + ((ch ^ (t & 7)) << 4) + sub;
      *reinterpret_cast<__half*>(sm + OFF_XH + off) = hi;
      *reinterpret_cast<__half*>(sm + OFF_XL + off) = lo;
    }
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
  // ---- GEMM2 swap-AB: D2[out][tok] = W2h.X2h (cols 128..) and W2h.X2l + W2l.X2h (cols 256..), K = 128
  if (warp == 0) {
    const uint32_t id = idesc_kk(NP);
#pragma unroll
    for (int kk = 0; kk < 8; kk++) {
      const uint32_t w = (kk & 3) * 32;
      mma_issue(tmem + 128, sdesc(sb + OFF_W2H + (kk >> 2) * 16384 + w), sdesc(sb + OFF_XH + (kk >> 2) * XATOM + w), id,
                kk ? 1u : 0u);
    }
#pragma unroll
    for (int pr = 0; pr < 2; pr++) {
      const uint32_t A = pr ? OFF_W2L : OFF_W2H;
      const uint32_t Bo = pr ? OFF_XH : OFF_XL;
#pragma unroll
      for (int kk = 0; kk < 8; kk++) {
        const uint32_t w = (kk & 3) * 32;
        mma_issue(tmem + 256, sdesc(sb + A + (kk >> 2) * 16384 + w), sdesc(sb + Bo + (kk >> 2) * XATOM + w), id,
                  (pr | kk) ? 1u : 0u);
      }
    }
    mma_commit(bar2);
  }
  mbar_wait(bar2, 0);
  tc_after();
  {
    float m[CW], c[CW];
    tmem_ld<CW>(tq + 128, m);
    tmem_ld<CW>(tq + 256, c);
    float* ob = p.out + (size_t)tok0 * 128 + hid;  // hid = output channel here
#pragma unroll
    for (int e = 0; e < CW; e++) {
      const int t = cq * CW + e;
      if (t < TT) atomicAdd(ob + (size_t)t * 128, m[e] + c[e]);
    }
  }
  tc_before();
  __syncthreads();
  if (warp == 0) {
    tc_after();
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory");
  }
}

template <int TT>
const char* e2_launch(const E2Params& p, int N, cudaStream_t stream) {
  static bool attr_set = false;
  cudaError_t e;
  if (!attr_set) {
    e = cudaFuncSetAttribute(e2_kernel<TT>, cudaFuncAttributeMaxDynamicSharedMemorySize, E2_SMEM);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    attr_set = true;
  }
  E2Params q = p;
  void* args[] = {(void*)&q};
  e = cudaLaunchCooperativeKernel((const void*)e2_kernel<TT>, dim3(4 * (N / TT)), dim3(E2_NTH), args, (size_t)E2_SMEM, stream);
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
}  // namespace

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream) {
  const int N = B * HW;
  // e2 path: smallest token tile that divides HW and keeps 4 slices x tiles within one wave of 148 CTAs
  int tt = 0;
  const int cands[3] = {28, 49, 98};
  for (int i = 0; i < 3 && !tt; i++)
    if (HW % cands[i] == 0 && 4 * (N / cands[i]) <= 148) tt = cands[i];
  if (tt) {
    E2Params p{x, w1, b1, gw, gb, w2, b2, out, nf, B, HW, eps};
    if (tt == 28) return e2_launch<28>(p, N, stream);
    if (tt == 49) return e2_launch<49>(p, N, stream);
    return e2_launch<98>(p, N, stream);
  }
  static bool attrs_set = false;
  if (!attrs_set) {
    cudaFuncSetAttribute(k_stats, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_STATS);
    cudaFuncSetAttribute(k_main, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_MAIN);
    attrs_set = true;
  }
  const int tiles = (HW + TM - 1) / TM;
  dim3 grid(tiles, B);
  k_stats<<<grid, NT, SMEM_STATS, stream>>>(x, w1, b1, part, HW, tiles);
  k_grn<<<B, HID, 0, stream>>>(part, nf, tiles, eps);
  k_main<<<grid, NT, SMEM_MAIN, stream>>>(x, w1, b1, gw, gb, w2, b2, nf, out, HW);
  return nullptr;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" const char* launch_grn_mlp(const float* x, const float* w1, const float* b1, const float* gw, const float* gb,
                                      const float* w2, const float* b2, float eps, float* out, float* part, float* nf,
                                      int B, int HW, cudaStream_t stream);

void run(torch::Tensor hidden_states, torch::Tensor pwconv1_weight, torch::Tensor pwconv1_bias,
         torch::Tensor grn_weight, torch::Tensor grn_bias, torch::Tensor pwconv2_weight, torch::Tensor pwconv2_bias,
         double eps, torch::Tensor output) {
  TORCH_CHECK(hidden_states.is_cuda() && hidden_states.scalar_type() == torch::kFloat32, "fp32 CUDA input");
  TORCH_CHECK(hidden_states.dim() == 4 && hidden_states.size(3) == 128, "[B,H,W,128]");
  TORCH_CHECK(pwconv1_weight.size(0) == 512 && pwconv1_weight.size(1) == 128, "W1 [512,128]");
  TORCH_CHECK(pwconv2_weight.size(0) == 128 && pwconv2_weight.size(1) == 512, "W2 [128,512]");
  for (auto* t : {&hidden_states, &pwconv1_weight, &pwconv1_bias, &grn_weight, &grn_bias, &pwconv2_weight,
                  &pwconv2_bias, &output})
    TORCH_CHECK(t->is_contiguous(), "contiguous tensors required");
  const c10::cuda::CUDAGuard guard(hidden_states.device());
  const int B = (int)hidden_states.size(0);
  const int HW = (int)(hidden_states.size(1) * hidden_states.size(2));
  const int tiles = (HW + 63) / 64;
  auto part = torch::empty({(int64_t)B * tiles * 512}, hidden_states.options());
  auto nf = torch::empty({(int64_t)B * 512}, hidden_states.options());
  const char* err = launch_grn_mlp(hidden_states.data_ptr<float>(), pwconv1_weight.data_ptr<float>(),
                                   pwconv1_bias.data_ptr<float>(), grn_weight.data_ptr<float>(), grn_bias.data_ptr<float>(),
                                   pwconv2_weight.data_ptr<float>(), pwconv2_bias.data_ptr<float>(), (float)eps,
                                   output.data_ptr<float>(), part.data_ptr<float>(), nf.data_ptr<float>(), B, HW,
                                   at::cuda::getCurrentCUDAStream());
  TORCH_CHECK(err == nullptr, err ? err : "");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "fused linear-gelu-grn-linear"); }

// 045_fused_linear_gelu_grn_linear, lineage B (r1 E2): hidden-slice fan-out for N <= 3136 tokens.
//   e2: grid = token tiles x 4 hidden slices of 128 (one wave, 1 CTA/SM, cooperative). Each CTA LDGs its fp32 slices
//       W1[slice,:], W2[:,slice] and its x tile, splits them into fp16 hi/lo SW128 smem images, runs GEMM1 swap-AB
//       (D1[hid][tok], FP16x3) into TMEM, + b1, A&S GELU, per-channel sumsq red.add into gsum[b][512] (zeroed by CTA 0
//       behind a flag), one grid counter (departure reset), GRN scale, x2 = gw*(h*nf) + gb + h split hi/lo, GEMM2
//       swap-AB (D2[out][tok], main + cross accumulators) and red.add into out (prefilled with b2 by the slice-0 CTA).
//   other shapes: r0 fp32 SIMT, three launches.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>

struct E2Params {
  const float* x; const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out; float* gsum; int B; int HW; float eps;
};

// [0] gsum-zeroed flag, [1] arrivals, [2] departures; the last departer resets all three for the next call
__device__ unsigned int g_e2ctr[4];

namespace {
// ------------------------------------------------------------------ r0 fallback (fp32 SIMT, 3 launches)
constexpr int D = 128, HID = 512, TM = 64, NC = 64, NT = 256;
constexpr int NCHUNK = HID / NC;
constexpr int LDK = D + 4;
constexpr int LDH = NC + 4;

__device__ __forceinline__ float gelu_erf(float v) {
  return v * 0.5f * (1.0f + erff(v * 0.7071067811865476f));
}

__device__ __forceinline__ void load_rows128(float* dst, const float* src, int nrows, int nvalid, int tid) {
  for (int i = tid; i < nrows * (D / 4); i += NT) {
    int r = i >> 5, k4 = (i & 31) << 2;
    float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
    if (r < nvalid) v = __ldg(reinterpret_cast<const float4*>(src + (size_t)r * D + k4));
    *reinterpret_cast<float4*>(dst + r * LDK + k4) = v;
  }
}

__device__ __forceinline__ void gemm1(float (&acc)[4][4], const float* As, const float* Ws, int tm, int tn) {
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.f;
#pragma unroll 4
  for (int k = 0; k < D; k += 4) {
    float4 a[4], w[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(As + (tm * 4 + i) * LDK + k);
#pragma unroll
    for (int j = 0; j < 4; ++j) w[j] = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDK + k);
#pragma unroll
    for (int i = 0; i < 4; ++i)
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        acc[i][j] = fmaf(a[i].x, w[j].x, acc[i][j]);
        acc[i][j] = fmaf(a[i].y, w[j].y, acc[i][j]);
        acc[i][j] = fmaf(a[i].z, w[j].z, acc[i][j]);
        acc[i][j] = fmaf(a[i].w, w[j].w, acc[i][j]);
      }
  }
}

__global__ void __launch_bounds__(NT) k_stats(const float* __restrict__ x, const float* __restrict__ w1,
                                              const float* __restrict__ b1, float* __restrict__ part,
                                              int HW, int tiles) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Red = Ws + NC * LDK;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  float* pout = part + ((size_t)b * tiles + tile) * HID;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
    float sq[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      float bias = __ldg(b1 + c * NC + tn + 16 * j);
      float s = 0.f;
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        if (tm * 4 + i < rows) s = fmaf(h, h, s);
      }
      s += __shfl_xor_sync(0xffffffffu, s, 16);
      sq[j] = s;
    }
    if (lane < 16) {
#pragma unroll
      for (int j = 0; j < 4; ++j) Red[warp * NC + tn + 16 * j] = sq[j];
    }
    __syncthreads();
    if (tid < NC) {
      float s = 0.f;
#pragma unroll
      for (int w = 0; w < NT / 32; ++w) s += Red[w * NC + tid];
      pout[c * NC + tid] = s;
    }
  }
}

__global__ void __launch_bounds__(HID) k_grn(const float* __restrict__ part, float* __restrict__ nf, int tiles,
                                             float eps) {
  __shared__ float red[HID / 32];
  const int b = blockIdx.x, c = threadIdx.x;
  const float* p = part + (size_t)b * tiles * HID + c;
  float s = 0.f;
  for (int t = 0; t < tiles; ++t) s += p[(size_t)t * HID];
  float g = __fsqrt_rn(s);
  float r = g;
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) r += __shfl_xor_sync(0xffffffffu, r, o);
  if ((c & 31) == 0) red[c >> 5] = r;
  __syncthreads();
  float tot = 0.f;
#pragma unroll
  for (int w = 0; w < HID / 32; ++w) tot += red[w];
  float mean = __fdiv_rn(tot, (float)HID);
  nf[(size_t)b * HID + c] = __fdiv_rn(g, mean + eps);
}

__global__ void __launch_bounds__(NT) k_main(const float* __restrict__ x, const float* __restrict__ w1,
                                             const float* __restrict__ b1, const float* __restrict__ gw,
                                             const float* __restrict__ gb, const float* __restrict__ w2,
                                             const float* __restrict__ b2, const float* __restrict__ nf,
                                             float* __restrict__ out, int HW) {
  extern __shared__ float4 smem4[];
  float* As = reinterpret_cast<float*>(smem4);
  float* Ws = As + TM * LDK;
  float* Hs = Ws + D * LDH;
  const int tile = blockIdx.x, b = blockIdx.y, tid = threadIdx.x;
  const int tm = tid >> 4, tn = tid & 15;
  const int m0 = tile * TM, rows = min(TM, HW - m0);
  load_rows128(As, x + ((size_t)b * HW + m0) * D, TM, rows, tid);
  const float* nfb = nf + (size_t)b * HID;
  float acc2[4][8];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int j = 0; j < 8; ++j) acc2[i][j] = 0.f;
  for (int c = 0; c < NCHUNK; ++c) {
    __syncthreads();
    load_rows128(Ws, w1 + (size_t)c * NC * D, NC, NC, tid);
    __syncthreads();
    float acc[4][4];
    gemm1(acc, As, Ws, tm, tn);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      const int n = c * NC + tn + 16 * j;
      const float bias = __ldg(b1 + n), g = __ldg(gw + n), be = __ldg(gb + n), f = __ldg(nfb + n);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float h = gelu_erf(acc[i][j] + bias);
        Hs[(tm * 4 + i) * LDH + tn + 16 * j] = g * (h * f) + be + h;
      }
    }
    __syncthreads();
    for (int i = tid; i < D * (NC / 4); i += NT) {
      int o = i >> 4, k4 = (i & 15) << 2;
      *reinterpret_cast<float4*>(Ws + o * LDH + k4) =
          __ldg(reinterpret_cast<const float4*>(w2 + (size_t)o * HID + c * NC + k4));
    }
    __syncthreads();
#pragma unroll 2
    for (int k = 0; k < NC; k += 4) {
      float4 a[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) a[i] = *reinterpret_cast<const float4*>(Hs + (tm * 4 + i) * LDH + k);
#pragma unroll
      for (int j = 0; j < 8; ++j) {
        float4 w = *reinterpret_cast<const float4*>(Ws + (tn + 16 * j) * LDH + k);
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          acc2[i][j] = fmaf(a[i].x, w.x, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].y, w.y, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].z, w.z, acc2[i][j]);
          acc2[i][j] = fmaf(a[i].w, w.w, acc2[i][j]);
        }
      }
    }
  }
  float* ob = out + ((size_t)b * HW + m0) * D;
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int o = tn + 16 * j;
    const float bias = __ldg(b2 + o);
#pragma unroll
    for (int i = 0; i < 4; ++i)
      if (tm * 4 + i < rows) ob[(size_t)(tm * 4 + i) * D + o] = acc2[i][j] + bias;
  }
}

constexpr int SMEM_STATS = (TM * LDK + NC * LDK + (NT / 32) * NC) * 4;
constexpr int SMEM_MAIN = (TM * LDK + D * LDH + TM * LDH) * 4;
static_assert(D * LDH >= NC * LDK, "Ws must hold either chunk");

// ------------------------------------------------------------------ e2: hidden-slice fan-out (tcgen05 FP16x3)
constexpr int E2_NTH = 512;
constexpr int OFF_W1H = 0, OFF_W1L = 32768;      // W1 slice [128 hid][128 k] K-major SW128, hi / lo
constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
constexpr int OFF_VEC = 196608;                  // b1, gw, gb, nf slices [128] each
constexpr int OFF_SSP = 198656;                  // sumsq partials [4 column quarters][128]
constexpr int OFF_RED = 200704;                  // [16]
constexpr int OFF_BAR = 200960;                  // 2 mbarriers + TMEM slot
constexpr int E2_SMEM = 201024 + 1024;

__device__ __forceinline__ uint32_t s_addr(const void* q) { return (uint32_t)__cvta_generic_to_shared(q); }
__device__ __forceinline__ void mbar_init(uint32_t b, uint32_t n) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(b), "r"(n)); }
__device__ __forceinline__ void mbar_wait(uint32_t b, uint32_t par) {
  asm volatile("{\n.reg .pred P;\nWAIT_%=:\nmbarrier.try_wait.parity.shared::cta.b64 P, [%0], %1;\n@!P bra WAIT_%=;\n}\n" ::"r"(b), "r"(par) : "memory");
}
__device__ __forceinline__ void fence_proxy_async() { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); }
__device__ __forceinline__ void tc_before() { asm volatile("tcgen05.fence::before_thread_sync;" ::: "memory"); }
__device__ __forceinline__ void tc_after() { asm volatile("tcgen05.fence::after_thread_sync;" ::: "memory"); }
__device__ __forceinline__ uint64_t sdesc(uint32_t addr) {  // K-major SWIZZLE_128B, SBO 1024, sm100 descriptor version 1
  return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | (1ull << 46) | (2ull << 61);
}
// kind::f16: fp32 D, fp16 A/B, both K-major, M = 128
__device__ __forceinline__ uint32_t idesc_kk(int n) { return (1u << 4) | ((uint32_t)(n >> 3) << 17) | ((128u >> 4) << 24); }
__device__ __forceinline__ void mma_issue(uint32_t d, uint64_t a, uint64_t b, uint32_t id, uint32_t acc) {
  asm volatile("{\n.reg .pred E, A;\nelect.sync _|E, 0xffffffff;\nsetp.ne.u32 A, %4, 0;\n"
               "@E tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, A;\n}\n" ::"r"(d), "l"(a), "l"(b), "r"(id), "r"(acc) : "memory");
}
__device__ __forceinline__ void mma_commit(uint32_t bar) {
  asm volatile("{\n.reg .pred E;\nelect.sync _|E, 0xffffffff;\n"
               "@E tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}\n" ::"r"(bar) : "memory");
}
template <int N>
__device__ __forceinline__ void tmem_ld(uint32_t ta, float (&v)[N]) {
  uint32_t r[N];
#pragma unroll
  for (int i = 0; i < N / 4; i++)
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r[4 * i]), "=r"(r[4 * i + 1]), "=r"(r[4 * i + 2]), "=r"(r[4 * i + 3]) : "r"(ta + 4 * i) : "memory");
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
  for (int i = 0; i < N; i++) {
    asm volatile("" : "+r"(r[i]));  // uses stay behind the wait
    v[i] = __uint_as_float(r[i]);
  }
}
__device__ __forceinline__ uint32_t ld_acquire(const unsigned int* q) {
  uint32_t v;
  asm volatile("ld.acquire.gpu.global.u32 %0, [%1];" : "=r"(v) : "l"(q) : "memory");
  return v;
}
__device__ __forceinline__ void red_release(unsigned int* q, uint32_t v) {
  asm volatile("red.release.gpu.global.add.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ void st_release(unsigned int* q, uint32_t v) {
  asm volatile("st.release.gpu.global.u32 [%0], %1;" ::"l"(q), "r"(v) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// GELU (erf form) on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0)   (#129 gelu2 without the sumsq)
__device__ __forceinline__ void gelu2(float& x0, float& x1) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  f2unpack(add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f))), x0, x1);
}
// 4 consecutive k of row r into the hi and lo K-major SW128 images (atom = 64 k = 128 B per row)
__device__ __forceinline__ void put_hilo(unsigned char* sm, int offh, int offl, int atom_bytes, int r, int c4, float4 v) {
  const int off = (c4 >> 4) * atom_bytes + r * 128 + ((((c4 >> 1) & 7) ^ (r & 7)) << 4) + (c4 & 1) * 8;
  const __half2 h01 = __floats2half2_rn(v.x, v.y), h23 = __floats2half2_rn(v.z, v.w);
  const float2 f01 = __half22float2(h01), f23 = __half22float2(h23);
  const __half2 l01 = __floats2half2_rn(v.x - f01.x, v.y - f01.y), l23 = __floats2half2_rn(v.z - f23.x, v.w - f23.y);
  *reinterpret_cast<uint2*>(sm + offh + off) = make_uint2(h2u(h01), h2u(h23));
  *reinterpret_cast<uint2*>(sm + offl + off) = make_uint2(h2u(l01), h2u(l23));
}

template <int TT>
__global__ void __launch_bounds__(E2_NTH, 1) e2_kernel(const E2Params p) {
  constexpr int NP = (TT + 15) / 16 * 16;  // MMA N (tokens, padded)
  constexpr int CW = NP / 4;               // columns per thread in the epilogues
  constexpr int XATOM = NP * 128;          // bytes per 64-k atom of a token-row image
  constexpr int NXL = NP / 16;             // x float4 per thread
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int slice = blockIdx.x & 3, tile = blockIdx.x >> 2, tok0 = tile * TT, b = tok0 / p.HW;
  float* s_b1 = (float*)(sm + OFF_VEC);
  float* s_gw = s_b1 + 128;
  float* s_gb = s_b1 + 256;
  float* s_nf = s_b1 + 384;
  float* s_ssp = (float*)(sm + OFF_SSP);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar1 = sb + OFF_BAR, bar2 = bar1 + 8;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 16);
  unsigned int* ctr = g_e2ctr;

  // ---- every global load up front: W1 slice (contiguous 64 KB), x tile, W2 slice (128 rows x 512 B), b1/gw/gb slices
  float4 vw1[8], vx[NXL], vw2[8], vv = make_float4(0.f, 0.f, 0.f, 0.f);
  const float4* w1s = reinterpret_cast<const float4*>(p.w1 + (size_t)slice * 128 * 128);
#pragma unroll
  for (int i = 0; i < 8; i++) vw1[i] = __ldg(w1s + tid + E2_NTH * i);
  const float4* xs = reinterpret_cast<const float4*>(p.x + (size_t)tok0 * 128);
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    vx[i] = ((f >> 5) < TT) ? __ldg(xs + f) : make_float4(0.f, 0.f, 0.f, 0.f);
  }
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    vw2[i] = __ldg(reinterpret_cast<const float4*>(p.w2 + (size_t)(f >> 5) * 512 + slice * 128) + (f & 31));
  }
  if (tid < 96) {
    const float* src = tid < 32 ? p.b1 : (tid < 64 ? p.gw : p.gb);
    vv = __ldg(reinterpret_cast<const float4*>(src + slice * 128) + (tid & 31));
  }
  if (tid == 0) {
    mbar_init(bar1, 1);
    mbar_init(bar2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  if (blockIdx.x == 0)
    for (int i = tid; i < p.B * 512; i += E2_NTH) p.gsum[i] = 0.f;
  if (tid < 96) reinterpret_cast<float4*>(s_b1)[tid] = vv;
#pragma unroll
  for (int i = 0; i < 8; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_W1H, OFF_W1L, 16384, f >> 5, f & 31, vw1[i]);
  }
#pragma unroll
  for (int i = 0; i < NXL; i++) {
    const int f = tid + E2_NTH * i;
    put_hilo(sm, OFF_XH, OFF_XL, XATOM, f >> 5, f & 31, vx[i]);
  }
  fence_proxy_async();
  tc_before();
  __syncthreads();
  tc_after();
