  __syncthreads();
  STAMP(3)
  if (tid == 0) { __threadfence(); red_release(ctr + 1, 1u); while (ld_acquire(ctr + 1) < gridDim.x) { }
    const unsigned old = atomicAdd(ctr + 2, 1u);
