  }
  mbar_wait(bar2, 0); tc_after();
  STAMP(5)
  { float m[CW], c[CW]; tmem_ld<CW>(tq + 128, m); tmem_ld<CW>(tq + 256, c);
    float* ob = p.out + (size_t)tok0 * 128 + hid;
#pragma unroll
    for (int e = 0; e < CW; e++) { const int t = cq * CW + e; if (t < TT) atomicAdd(ob + (size_t)t * 128, m[e] + c[e]); } }
  tc_before(); __syncthreads();
