  if (warp == 0) { tc_after(); asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory"); }
}
template <int TT>
const char* e2_launch(const E2Params& p, int N, cudaStream_t stream) {
  static bool attr_set = false; cudaError_t e;
  if (!attr_set) { e = cudaFuncSetAttribute(e2_kernel<TT>, cudaFuncAttributeMaxDynamicSharedMemorySize, E2_SMEM); if (e != cudaSuccess) return cudaGetErrorString(e); attr_set = true; }
