constexpr int OFF_XH = 65536, OFF_XL = 98304;    // x tile [NP tok][128 k], later x2 [NP tok][128 hid], hi / lo
constexpr int OFF_W2H = 131072, OFF_W2L = 163840;  // W2 slice [128 out][128 hid], hi / lo
